window.PG_ENGINE = {"build": "#!/usr/bin/env python3\n\"\"\"Build viewer/data/<inst>.js from the engine's outputs, traces and the evidence markdown.\n\nusage: python3 viewer/build_data.py [--detail N] [--runs 5]\n  - summary rows for every case (queue, counters)\n  - full detail (graph, recon, docs, timeline) for N cases per institution (stratified by\n    reason code, always including the pinned demo cases)\n  - determinism fingerprint: re-runs system/run --runs times into a temp dir and hashes the outputs\n\"\"\"\nimport hashlib, json, os, re, subprocess, sys, tempfile\nfrom collections import defaultdict, OrderedDict\nfrom datetime import date\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nINSTS = [\"bank\", \"emoney\", \"investment\", \"payments_fx\"]\nMONTHS = [\"January\", \"February\", \"March\", \"April\", \"May\", \"June\", \"July\", \"August\", \"September\", \"October\",\n          \"November\", \"December\"]\nBOILER = {\"due_diligence_summary\", \"proof_of_address\", \"contact_note\"}\n\n\ndef arg(name, default):\n    return int(sys.argv[sys.argv.index(name) + 1]) if name in sys.argv else default\n\n\ndef jl(p):\n    with open(p, encoding=\"utf-8\") as fh:\n        return [json.loads(l) for l in fh if l.strip()]\n\n\ndef fmt(x):\n    return \"£{:,.2f}\".format(x)\n\n\ndef dtxt(iso):\n    m = re.match(r\"(\\d{4})-(\\d{2})-(\\d{2})\", str(iso or \"\"))\n    return \"%d %s %s\" % (int(m.group(3)), MONTHS[int(m.group(2)) - 1], m.group(1)) if m else None\n\n\ndef fingerprint(inst, runs):\n    hs = []\n    with tempfile.TemporaryDirectory() as td:\n        for k in range(runs):\n            out = os.path.join(td, \"%s.%d.jsonl\" % (inst, k))\n            subprocess.run([os.path.join(ROOT, \"system\", \"run\"), os.path.join(ROOT, \"institutions\", inst), out],\n                           check=True, stderr=subprocess.DEVNULL)\n            rows = jl(out)\n            vc = hashlib.sha256(\"\\n\".join(\"%s|%s|%s\" % (r[\"case_id\"], r[\"verdict\"], r[\"reason_code\"])\n                                          for r in rows).encode()).hexdigest()\n            full = hashlib.sha256(open(out, \"rb\").read()).hexdigest()\n            hs.append({\"run\": k + 1, \"verdict_code_hash\": vc[:12], \"file_hash\": full[:12]})\n    return hs\n\n\ndef pick_demos(outs, traces):\n    \"\"\"Three presenter pins chosen by criteria (not by ID), first match in file order.\"\"\"\n    def recs(o):\n        return traces[o[\"case_id\"]].get(\"reconciliation\", [])\n\n    def clean_close(o, codes):\n        r = recs(o)\n        return o[\"reason_code\"] in codes and r and all(x[\"cleared\"] and x[\"unexplained_gbp\"] == 0 and\n                                                      x[\"explained_gbp\"] > 0 for x in r) and \\\n            len(set(d for x in r for d in x[\"explained_by\"])) == 1\n\n    def esc_trap(o, need_contra):\n        t = traces[o[\"case_id\"]]\n        return o[\"reason_code\"] == \"ESC_LISTED_PARTY\" and (not need_contra or any(\n            e[\"rel\"] == \"contradicts\" for e in t[\"edges\"]))\n\n    def rfi_partial(o):\n        r = recs(o)\n        return o[\"verdict\"] == \"RFI\" and r and any(x[\"unexplained_gbp\"] > 0 for x in r) and \\\n            any(x[\"explained_gbp\"] + x.get(\"profile_gbp\", 0) > 0 for x in r)\n\n    tiers = {\n        \"close\": [lambda o: clean_close(o, {\"INVOICE_MATCHES\"}), lambda o: clean_close(o, {\n            \"DOCUMENTED_EVENT\", \"THIRD_PARTY_DOCUMENTED\", \"REFUND_OF_EARLIER_PAYMENT\", \"OWN_ACCOUNT\"}),\n                  lambda o: o[\"verdict\"] == \"CLOSE\"],\n        \"esc\": [lambda o: esc_trap(o, True), lambda o: esc_trap(o, False), lambda o: o[\"verdict\"] == \"ESCALATE\"],\n        \"rfi\": [rfi_partial, lambda o: o[\"verdict\"] == \"RFI\"],\n    }\n    demo = {}\n    for k, fs in tiers.items():\n        for f in fs:\n            hit = next((o[\"case_id\"] for o in outs if f(o)), None)\n            if hit:\n                demo[k] = hit\n                break\n    return demo\n\n\ndef recon_segments(o, t, tx, cust_name):\n    recs = t.get(\"reconciliation\", [])\n    explains = defaultdict(list)\n    for e in t[\"edges\"]:\n        if e[\"rel\"] == \"explains\":\n            explains[e[\"to\"]].append(e[\"from\"])\n    alerted = []\n    for r in recs:\n        pass\n    seen, segs = set(), OrderedDict()\n    onward_docs = sorted(set(d for tid, ds in explains.items() for d in ds))\n    cleared_alert_txn, unexpl = set(), set()\n    alert_txns = OrderedDict()\n    for n in t[\"nodes\"]:\n        pass\n    for e in t[\"edges\"]:\n        if e[\"rel\"] == \"fired_on\" and e[\"from\"] in o[\"alert_ids\"] and e[\"to\"] in tx:\n            alert_txns.setdefault(e[\"to\"], set()).add(e[\"from\"])\n    rec_by_alert = {r[\"alert_id\"]: r for r in recs}\n    for r in recs:\n        for x in r.get(\"unexplained_txns\", []):\n            if not r[\"cleared\"]:\n                unexpl.add(x)\n    profile_note = {}\n    for tid in alert_txns:\n        x = tx[tid]\n        amt = x[\"amount_gbp\"]\n        al_cleared = all(rec_by_alert.get(a, {}).get(\"cleared\") for a in alert_txns[tid])\n        if explains.get(tid):\n            key = (\"doc\", sorted(explains[tid])[0])\n        elif tid in unexpl:\n            key = (\"unexplained\", None)\n        else:\n            key = (\"profile\", None)\n        s = segs.setdefault(key, {\"kind\": key[0], \"doc\": key[1], \"amount\": 0.0, \"txns\": []})\n        s[\"amount\"] = round(s[\"amount\"] + amt, 2)\n        s[\"txns\"].append(tid)\n    order = sorted(segs.values(), key=lambda s: ({\"doc\": 0, \"profile\": 1, \"unexplained\": 2}[s[\"kind\"]], s[\"doc\"] or \"\"))\n    total = round(sum(s[\"amount\"] for s in order), 2)\n    unex = round(sum(s[\"amount\"] for s in order if s[\"kind\"] == \"unexplained\"), 2)\n    return {\"total\": total, \"unexplained\": unex, \"segments\": order,\n            \"rule_view\": [{\"alert\": r[\"alert_id\"], \"rule\": r[\"rule\"], \"alerted\": r[\"alerted_gbp\"],\n                           \"explained\": r[\"explained_gbp\"], \"unexplained\": r[\"unexplained_gbp\"],\n                           \"cleared\": r[\"cleared\"], \"limit\": r.get(\"limit_gbp\"),\n                           \"residual\": r.get(\"residual_activity_gbp\")} for r in recs]}\n\n\ndef highlights(doc_id, o, t, tx, cname):\n    sup, con = set(), set()\n    linked = set()\n    for e in t[\"edges\"]:\n        if e[\"from\"] == doc_id and e[\"to\"] in tx:\n            linked.add(e[\"to\"])\n    for tid in linked:\n        x = tx[tid]\n        sup.add(fmt(x[\"amount_gbp\"]))\n        if x.get(\"counterparty_name\"):\n            sup.add(x[\"counterparty_name\"])\n        d = dtxt(x[\"booked_at\"])\n        if d:\n            sup.add(d)\n        if x.get(\"reference\") and len(x[\"reference\"]) > 5:\n            sup.add(x[\"reference\"])\n    if cname:\n        sup.add(cname)\n    contra_doc = any(e[\"rel\"] == \"contradicts\" and doc_id in (e[\"from\"], e[\"to\"]) for e in t[\"edges\"])\n    for f in t.get(\"facts\", []):\n        if doc_id not in f.get(\"sources\", []):\n            continue\n        vals = []\n        for k, v in f.items():\n            if k in (\"id\", \"kind\", \"sources\", \"rule\", \"code\") or v is None or isinstance(v, (dict, list)):\n                continue\n            v = str(v)\n            vals.append(dtxt(v) or v)\n            m = re.match(r\"(\\d{4})-(\\d{2})\", v)\n            if m and re.search(r\"dob|born|birth\", k):\n                vals.append(\"%s %s\" % (MONTHS[int(m.group(2)) - 1], m.group(1)))\n        rose = contra_doc or \"differs\" in f[\"kind\"] or (o[\"verdict\"] == \"ESCALATE\" and \"explains\" != f[\"kind\"])\n        (con if rose else sup).update(x for x in vals if x and len(x) >= 3)\n    for e in o[\"evidence\"]:\n        sup.add(e)\n    for n in t[\"nodes\"]:\n        if n[\"type\"] == \"list_entry\" and contra_doc or (n[\"type\"] == \"list_entry\" and o[\"verdict\"] == \"ESCALATE\"):\n            con.add(n.get(\"label\") or \"\")\n    for x in t.get(\"list_resolution\", []):\n        if x.get(\"lname\") and doc_id in (x.get(\"docs\") or []):\n            (con if x.get(\"status\") == \"confirmed\" else sup).add(x[\"lname\"])\n    sup -= con\n    return {\"sup\": sorted(sup, key=lambda s: -len(s)), \"con\": sorted(con, key=lambda s: -len(s))}\n\n\nRULE_WORDS = {\"TM01\": \"Activity above declared profile\", \"TM02\": \"Money in and straight out\", \"TM03\": \"Payments just under a threshold\",\n              \"TM04\": \"Many counterparties\", \"TM05\": \"Large cash\", \"TM06\": \"Higher-risk country\", \"TM07\": \"Dormant account reactivated\",\n              \"TM08\": \"Third-party money\", \"TM10\": \"Early fund redemption\", \"TM22\": \"Internal watch-list match\"}\n\n\ndef _d(iso):\n    return dtxt(iso) or str(iso or \"\")\n\n\ndef _short(iso):\n    m = re.match(r\"(\\d{4})-(\\d{2})-(\\d{2})\", str(iso or \"\"))\n    return \"%d %s\" % (int(m.group(3)), MONTHS[int(m.group(2)) - 1][:3]) if m else str(iso or \"\")\n\n\ndef build_story(o, t, tx, alerts, cust, docs_by_id):\n    \"\"\"Plain-English check cards, generated deterministically from the trace (no LLM).\"\"\"\n    facts = {f[\"id\"]: f for f in t.get(\"facts\", [])}\n    fl = t.get(\"facts\", [])\n    cards = []\n    def card(status, title, detail, docs, weight=0):\n        cards.append({\"status\": status, \"title\": title, \"detail\": detail, \"docs\": [x for x in docs if x], \"w\": weight})\n    kinds = defaultdict(list)\n    for f in fl:\n        kinds[f[\"kind\"]].append(f)\n    lr = {x.get(\"entry\"): x for x in t.get(\"list_resolution\", [])}\n    lname = next((x.get(\"lname\") for x in t.get(\"list_resolution\", []) if x.get(\"lname\")), \"the listed person\")\n    docsrc = lambda f: [x for x in f[\"sources\"] if x in docs_by_id]\n    # suspicion and list facts\n    for f in kinds[\"listed_person_controlled_counterparty_at_payment\"]:\n        pct = re.search(r\"\\((\\d+%)\\)\", f.get(\"control\") or \"\")\n        res = kinds[\"officer_resigned_before_payment\"]\n        lead = (\"Resigned as director %s, but \" % _short(res[0][\"resigned\"])) if res else \"\"\n        card(\"fail\", \"%s still controlled the payee when it was paid\" % lname,\n             \"%sheld %s until %s; the payment was on %s.\" % (lead, pct.group(1) if pct else \"control\",\n                                                            _short(f.get(\"ceased\")) if f.get(\"ceased\") else \"now\",\n                                                            _short(f.get(\"payment\"))),\n             docsrc(f) + [x for r in res for x in r[\"sources\"]], 10)\n    for f in kinds[\"counterparty_dob_equals_list_dob\"]:\n        card(\"fail\", \"Donor's date of birth matches the list entry\", \"Born %s, the same as %s on the internal list.\" % (\n            _d(f[\"dob\"]), lname), docsrc(f), 10)\n    for f in kinds[\"counterparty_dob_differs_from_list\"]:\n        card(\"pass\", \"Different person from the list entry\", \"Donor born %s; %s was born %s.\" % (\n            _d(f[\"dob\"]), lname, _d(f.get(\"list_dob\"))), docsrc(f), 6)\n    for f in kinds[\"counterparty_address_differs_from_list\"]:\n        card(\"pass\", \"Different party from the list entry\", \"Payee is at %s; %s is linked to %s.\" % (\n            f.get(\"counterparty_unit\"), lname, f.get(\"list_unit\")), docsrc(f), 6)\n    for f in kinds.get(\"officer_birth_differs_from_list\", []):\n        card(\"pass\", \"Different person from the list entry\", \"Register birth date differs from %s's.\" % lname, docsrc(f), 6)\n    sc = kinds[\"scam_report_sender_paid_customer\"]\n    if sc:\n        senders = sorted(set(f.get(\"sender\") for f in sc if f.get(\"sender\")))\n        card(\"fail\", \"%d scam report%s name people who paid this account\" % (len(sc), \"\" if len(sc) == 1 else \"s\"),\n             \"Senders %s, %s in total.\" % (\", \".join(senders[:3]), fmt(sum(f.get(\"amount\") or 0 for f in sc))),\n             sorted(set(x for f in sc for x in docsrc(f))), 10)\n    TPL = {\n        \"customer_invests_for_third_parties\": (\"Customer says they handle other people's money\", lambda f: \"\\u201c%s\\u201d\" % f.get(\"quote\", \"\")),\n        \"payer_company_dissolved_before_payment\": (\"Payer company no longer existed\", lambda f: \"%s was dissolved on %s, before it paid.\" % (f.get(\"company\"), _d(f.get(\"dissolved_on\")))),\n        \"customer_asked_how_to_avoid_threshold\": (\"Customer asked how to stay under a threshold\", lambda f: \"Recorded in a staff note.\"),\n        \"split_payments_to_unrelated_people_in_high_risk_country\": (\"Money split between unrelated people in %s\", lambda f: \"No document shows who they are.\"),\n        \"funds_routed_to_new_companies_of_same_director\": (\"Money passed on to the director's new companies\", lambda f: \"Companies set up recently by %s.\" % (f.get(\"director\") or \"\").title()),\n        \"device_shared_with_other_customers\": (\"Device shared with other customers\", lambda f: \"%d customer IDs use it; logins from %s.\" % (len(f.get(\"customers\") or []), f.get(\"countries\"))),\n        \"client_cannot_explain_corridor\": (\"Client can't explain the routing to %s\", lambda f: \"Recorded in a staff note.\"),\n        \"invoice_goods_inconsistent_with_business\": (\"Invoices don't fit the business\", lambda f: \"%s, for a business that %s.\" % (f.get(\"goods\"), (f.get(\"business_activity\") or \"\").lower())),\n        \"payees_share_addresses_inconsistent_with_country\": (\"Payees abroad share UK addresses\", lambda f: \"%s payees listed abroad have UK addresses.\" % f.get(\"uk_address_abroad\")),\n        \"customer_gives_conflicting_explanations\": (\"Customer gave conflicting stories\", lambda f: \"%s, then %s.\" % (\" / \".join(f.get(\"first\") or []), \" / \".join(f.get(\"second\") or []))),\n        \"suspicion_keyword\": (\"Documents mention %s\", lambda f: \"Unexplained activity plus a fraud indicator.\"),\n    }\n    for k, (title, det) in TPL.items():\n        for f in kinds.get(k, [])[:1]:\n            tt = title % (f.get(\"country\") or f.get(\"word\") or \"\") if \"%s\" in title else title\n            card(\"fail\", tt, det(f), docsrc(f) or f[\"sources\"][:2], 9)\n    # explanations (decisive and advisory)\n    seen_docs = set()\n    for fr in t.get(\"firings\", []):\n        if not re.match(r\"X\\d+_\", fr[\"rule\"]):\n            continue\n        ds = [d for d in fr.get(\"docs\", []) if d in docs_by_id]\n        if not ds or ds[0] in seen_docs:\n            continue\n        seen_docs.add(ds[0])\n        txs = sorted([tx[x] for x in fr.get(\"txns\", []) if x in tx], key=lambda x: -x[\"amount_gbp\"])\n        d0 = docs_by_id[ds[0]]\n        what = d0.get(\"type\", \"\").replace(\"_\", \" \")\n        if fr[\"rule\"] == \"X2_own_account_statement\":\n            title = \"Statement %s proves it's the customer's own account\" % ds[0]\n        else:\n            title = \"%s %s matches %s\" % (what[:1].upper() + what[1:], ds[0], fmt(txs[0][\"amount_gbp\"]) if txs else \"the amounts\")\n        det = (\"%s %s %s on %s\" % (fmt(txs[0][\"amount_gbp\"]), \"from\" if txs[0][\"direction\"] == \"in\" else \"to\",\n                                   txs[0].get(\"counterparty_name\") or \"cash\", _short(txs[0][\"booked_at\"]))) if txs else \"\"\n        if len(txs) > 1:\n            det += \" and %d more\" % (len(txs) - 1)\n        card(\"pass\", title, det + \".\", ds, 5)\n    # reconciliation per alert\n    for r in t.get(\"reconciliation\", []):\n        words = RULE_WORDS.get(r[\"rule\"], r[\"rule\"])\n        if not r[\"cleared\"] and r[\"rule\"] != \"TM22\":\n            card(\"info\", \"%s of %s has no supporting document\" % (fmt(r[\"unexplained_gbp\"]), fmt(r[\"alerted_gbp\"])),\n                 \"%s alert %s is still open.\" % (words, r[\"alert_id\"]), r.get(\"explained_by\", []), 8)\n        if r.get(\"profile_gbp\", 0) > 0 and not any(c[\"title\"].startswith(\"Regular activity\") for c in cards):\n            card(\"pass\", \"Regular activity: %s\" % fmt(r[\"profile_gbp\"]), \"Within the declared profile (e.g. salary, card takings).\", [], 2)\n    for x in t.get(\"list_resolution\", []):\n        if x.get(\"status\") == \"unsettled\":\n            card(\"info\", \"Name-only match with %s\" % x.get(\"lname\"), \"Nothing on file settles whether it is the same person.\",\n                 [x.get(\"entry\")], 9)\n    if o[\"reason_code\"] == \"RFI_UPDATED_PROFILE\":\n        card(\"info\", \"Own money, but far above the declared profile\", \"Activity is 5x or more of what the customer declared.\", [], 9)\n    order = {\"fail\": 0, \"info\": 1, \"pass\": 2}\n    cards.sort(key=lambda c: (order[c[\"status\"]], -c[\"w\"]))\n    if o[\"verdict\"] == \"CLOSE\":\n        card(\"pass\", \"Nothing left unexplained\", \"Every alerted pound is booked against evidence: %s unexplained.\" % fmt(0), [], 1)\n        card(\"pass\", \"No red flags\", \"None of the suspicion rules fired on this customer's documents.\", [], 0)\n        cards.sort(key=lambda c: (order[c[\"status\"]], -c[\"w\"]))\n    for c in cards:\n        c.pop(\"w\", None)\n    money = []\n    for a in alerts:\n        amt = sum(tx[x][\"amount_gbp\"] for x in set(a[\"transaction_ids\"]) if x in tx)\n        money.append({\"alert\": a[\"alert_id\"], \"rule\": a[\"rule_id\"], \"words\": RULE_WORDS.get(a[\"rule_id\"], a[\"rule_id\"]),\n                      \"amount\": round(amt, 2)})\n    return {\"money\": money, \"checks\": cards[:5], \"more\": max(0, len(cards) - 5)}\n\n\ndef build(inst, detail_n, runs, base=None, out=None, extra=()):\n    \"\"\"Bundle for one institution. base/out default to the repo; the in-browser Import page passes its own.\"\"\"\n    base = base or os.path.join(ROOT, \"institutions\", inst)\n    out = out or os.path.join(ROOT, \"output\", inst + \".jsonl\")\n    outs = jl(out)\n    traces = {t[\"case_id\"]: t for t in jl(out + \".trace.jsonl\")}\n    cases = {c[\"case_id\"]: c for c in jl(os.path.join(base, \"cases.jsonl\"))}\n    alerts = {a[\"alert_id\"]: a for a in jl(os.path.join(base, \"alerts.jsonl\"))}\n    custs = {c[\"customer_id\"]: c for c in jl(os.path.join(base, \"customers.jsonl\"))}\n    txs_by = defaultdict(list)\n    for x in jl(os.path.join(base, \"transactions.jsonl\")):\n        txs_by[x[\"customer_id\"]].append(x)\n    docs_by = defaultdict(list)\n    for d in jl(os.path.join(base, \"evidence.jsonl\")):\n        docs_by[d[\"customer_id\"]].append(d)\n    reviews_by = defaultdict(list)\n    for r in jl(os.path.join(base, \"previous_reviews.jsonl\")):\n        reviews_by[r[\"customer_id\"]].append(r)\n    listed = {r[\"entry_id\"]: r for r in jl(os.path.join(base, \"internal_list.jsonl\"))}\n\n    demos = pick_demos(outs, traces)\n    # stratified detail subset: round-robin over reason codes in file order\n    by_code = defaultdict(list)\n    for o in outs:\n        by_code[o[\"reason_code\"]].append(o[\"case_id\"])\n    chosen = [c for c in demos.values() if c]\n    chosen += [c for c in extra if c not in chosen]\n    detail_n += len(chosen) - len([c for c in demos.values() if c])\n    i = 0\n    while len(chosen) < min(detail_n, len(outs)):\n        added = False\n        for code in sorted(by_code):\n            if i < len(by_code[code]) and len(chosen) < detail_n:\n                if by_code[code][i] not in chosen:\n                    chosen.append(by_code[code][i])\n                added = True\n        if not added:\n            break\n        i += 1\n    chosen = set(chosen)\n\n    rows, detail = [], {}\n    for o in outs:\n        c = cases[o[\"case_id\"]]\n        cust = custs.get(c[\"customer_id\"], {})\n        als = [alerts[a] for a in o[\"alert_ids\"] if a in alerts]\n        tx = {x[\"transaction_id\"]: x for x in txs_by[c[\"customer_id\"]]}\n        amt = round(sum(tx[t][\"amount_gbp\"] for t in set(x for a in als for x in a[\"transaction_ids\"]) if t in tx), 2)\n        rows.append({\"id\": o[\"case_id\"], \"name\": cust.get(\"name\", \"\"), \"rules\": [a[\"rule_id\"] for a in als],\n                     \"amount\": amt, \"verdict\": o[\"verdict\"], \"code\": o[\"reason_code\"],\n                     \"alerts\": len(o[\"alert_ids\"]), \"detail\": o[\"case_id\"] in chosen,\n                     \"reason\": o[\"reason\"], \"evidence\": o[\"evidence\"], \"alert_ids\": o[\"alert_ids\"],\n                     \"fired\": sorted(set(re.sub(r\"^R_TM22_.*\", \"R_TM22\", f[\"rule\"]) for f in traces[o[\"case_id\"]][\"firings\"]\n                                         if not f.get(\"advisory\")))})\n        if o[\"case_id\"] not in chosen:\n            continue\n        t = traces[o[\"case_id\"]]\n        rw = c.get(\"review_window\") or {}\n        lo, hi = rw.get(\"from\", \"\"), rw.get(\"to\", \"9999\")\n        alerted = set(x for a in als for x in a[\"transaction_ids\"])\n        graph_tx = set(n[\"id\"] for n in t[\"nodes\"] if n[\"type\"] == \"transaction\")\n        lo_pad = \"%s\" % (date.fromisoformat(lo).replace(day=1).isoformat() if lo else \"\")\n        timeline = [x for x in sorted(tx.values(), key=lambda x: (x[\"booked_at\"], x[\"transaction_id\"]))\n                    if (lo_pad <= x[\"booked_at\"][:10] <= hi) or x[\"transaction_id\"] in alerted or\n                    x[\"transaction_id\"] in graph_tx]\n        if len(timeline) > 160:\n            timeline = [x for x in timeline if x[\"transaction_id\"] in alerted or x[\"transaction_id\"] in graph_tx] + \\\n                       [x for x in timeline if x[\"transaction_id\"] not in alerted and\n                        x[\"transaction_id\"] not in graph_tx][-60:]\n            timeline.sort(key=lambda x: (x[\"booked_at\"], x[\"transaction_id\"]))\n        tl = [{\"id\": x[\"transaction_id\"], \"at\": x[\"booked_at\"], \"dir\": x[\"direction\"], \"amt\": x[\"amount_gbp\"],\n               \"cp\": x.get(\"counterparty_name\") or (\"cash · \" + (x.get(\"location\") or \"\")), \"ref\": x.get(\"reference\"),\n               \"ch\": x.get(\"channel\"), \"cc\": x.get(\"counterparty_country\"), \"ccy\": x.get(\"currency\"),\n               \"alerted\": x[\"transaction_id\"] in alerted} for x in timeline]\n        docs = []\n        for d in sorted(docs_by[c[\"customer_id\"]], key=lambda d: d[\"doc_id\"]):\n            try:\n                md = open(os.path.join(base, d.get(\"file\") or \"evidence/%s.md\" % d[\"doc_id\"]), encoding=\"utf-8\").read()\n            except OSError:\n                md = \"\"\n            docs.append({\"id\": d[\"doc_id\"], \"type\": d.get(\"type\"), \"title\": d.get(\"title\"), \"dated\": d.get(\"dated\"),\n                         \"boiler\": d.get(\"type\") in BOILER, \"md\": md,\n                         \"hl\": highlights(d[\"doc_id\"], o, t, tx, cust.get(\"name\"))})\n        detail[o[\"case_id\"]] = {\n            \"out\": o, \"case\": {\"opened_at\": c.get(\"opened_at\"), \"window\": rw, \"held\": c.get(\"held_payment_id\"),\n                               \"customer_id\": c[\"customer_id\"]},\n            \"customer\": {k: cust.get(k) for k in (\"customer_id\", \"name\", \"kind\", \"employer\", \"business_activity\",\n                                                  \"declared\", \"date_of_birth\", \"opened_at\") if k in cust},\n            \"alerts\": [{\"id\": a[\"alert_id\"], \"rule\": a[\"rule_id\"], \"measured\": a.get(\"measured\"),\n                        \"txns\": a[\"transaction_ids\"], \"message\": a.get(\"message\") or a.get(\"description\")}\n                       for a in als],\n            \"trace\": {k: t.get(k) for k in (\"nodes\", \"edges\", \"facts\", \"firings\", \"reconciliation\", \"list_resolution\")},\n            \"recon\": recon_segments(o, t, tx, cust.get(\"name\")),\n            \"timeline\": tl, \"docs\": docs,\n            \"reviews\": reviews_by.get(c[\"customer_id\"], []),\n            \"story\": build_story(o, t, tx, als, cust, {d[\"doc_id\"]: d for d in docs_by[c[\"customer_id\"]]}),\n            \"list\": [listed[e] for e in sorted(set(n[\"id\"] for n in t[\"nodes\"] if n[\"type\"] == \"list_entry\"))\n                     if e in listed],\n        }\n    fp = fingerprint(inst, runs) if runs else []\n    return {\"inst\": inst, \"rows\": rows, \"detail\": detail, \"demos\": demos, \"runs\": fp}\n\n\ndef ontology_js():\n    \"\"\"Class hierarchy from system/ontology/proof.owl + the engine's type->class maps, for the viewer.\"\"\"\n    import importlib.machinery, importlib.util\n    ld = importlib.machinery.SourceFileLoader(\"proof_run\", os.path.join(ROOT, \"system\", \"run\"))\n    spec = importlib.util.spec_from_loader(\"proof_run\", ld)\n    eng = importlib.util.module_from_spec(spec)\n    ld.exec_module(eng)\n    owl = open(os.path.join(ROOT, \"system\", \"ontology\", \"proof.owl\"), encoding=\"utf-8\").read()\n    parent, classes, props = {}, [], []\n    for m in re.finditer(r\"^proof:(\\w+)\\s+a owl:Class\\b([^\\n]*)\", owl, re.M):\n        classes.append(m.group(1))\n        sc = re.search(r\"rdfs:subClassOf proof:(\\w+)\", m.group(2))\n        if sc:\n            parent[m.group(1)] = sc.group(1)\n    for m in re.finditer(r\"^proof:(\\w+)\\s+a owl:(Object|Datatype)Property\", owl, re.M):\n        props.append((m.group(1), m.group(2)))\n    kids = defaultdict(list)\n    for c in classes:\n        kids[parent.get(c)].append(c)\n    lines = []\n    def walk(c, depth):\n        lines.append(\"  \" * depth + (\"└ \" if depth else \"\") + c)\n        for k in kids.get(c, []):\n            walk(k, depth + 1)\n    for c in kids[None]:\n        walk(c, 0)\n    lines.append(\"\")\n    lines.append(\"object properties:\")\n    lines += [\"  \" + p for p, k in props if k == \"Object\"]\n    data = {\"tree\": \"\\n\".join(lines), \"nodeClass\": eng.NODE_CLASS, \"docClass\": eng.DOC_CLASS, \"edgeProp\": eng.EDGE_PROP}\n    with open(os.path.join(ROOT, \"viewer\", \"data\", \"ontology.js\"), \"w\", encoding=\"utf-8\") as fh:\n        fh.write(\"window.PROOF_ONTOLOGY = %s;\\n\" % json.dumps(data, ensure_ascii=False, sort_keys=True))\n\n\ndef engine_js():\n    \"\"\"Engine + bundle builder sources and policy defaults, for the in-browser (Pyodide) Import page.\"\"\"\n    import importlib.machinery, importlib.util\n    ld = importlib.machinery.SourceFileLoader(\"proof_run\", os.path.join(ROOT, \"system\", \"run\"))\n    spec = importlib.util.spec_from_loader(\"proof_run\", ld)\n    eng = importlib.util.module_from_spec(spec)\n    ld.exec_module(eng)\n    run_src = open(os.path.join(ROOT, \"system\", \"run\"), encoding=\"utf-8\").read()\n    bd_src = open(os.path.abspath(__file__), encoding=\"utf-8\").read()\n    data = {\"run\": run_src, \"build\": bd_src, \"policy\": eng.POLICY, \"keys\": eng.POLICY_KEYS,\n            \"run_sha256\": hashlib.sha256(run_src.encode(\"utf-8\")).hexdigest()}\n    with open(os.path.join(ROOT, \"viewer\", \"data\", \"engine.js\"), \"w\", encoding=\"utf-8\") as fh:\n        fh.write(\"window.PG_ENGINE = %s;\\n\" % json.dumps(data, ensure_ascii=False, sort_keys=True))\n\n\ndef main():\n    detail_n, runs = arg(\"--detail\", 200), arg(\"--runs\", 5)\n    ontology_js()\n    engine_js()\n    bp = os.path.join(ROOT, \"viewer\", \"data\", \"briefs.json\")\n    briefs = json.load(open(bp, encoding=\"utf-8\")) if os.path.exists(bp) else {}\n    os.makedirs(os.path.join(ROOT, \"viewer\", \"data\"), exist_ok=True)\n    index = []\n    for inst in INSTS:\n        if not os.path.exists(os.path.join(ROOT, \"output\", inst + \".jsonl.trace.jsonl\")):\n            continue\n        data = build(inst, detail_n, runs)\n        for cid, d in data[\"detail\"].items():\n            if cid in briefs:\n                d[\"brief\"] = briefs[cid]\n        p = os.path.join(ROOT, \"viewer\", \"data\", inst + \".js\")\n        with open(p, \"w\", encoding=\"utf-8\") as fh:\n            fh.write(\"window.PROOF_DATA = window.PROOF_DATA || {};\\nwindow.PROOF_DATA[%s] = \" % json.dumps(inst))\n            json.dump(data, fh, ensure_ascii=False, separators=(\",\", \":\"))\n            fh.write(\";\\n\")\n        index.append(inst)\n        print(inst, \"rows\", len(data[\"rows\"]), \"detail\", len(data[\"detail\"]), \"demos\", data[\"demos\"],\n              \"runs\", [r[\"verdict_code_hash\"] for r in data[\"runs\"]], \"%.1f MB\" % (os.path.getsize(p) / 1e6))\n    with open(os.path.join(ROOT, \"viewer\", \"data\", \"index.js\"), \"w\") as fh:\n        fh.write(\"window.PROOF_INSTS = %s;\\n\" % json.dumps(index))\n\n\nif __name__ == \"__main__\":\n    main()\n", "keys": {"invoice_required_gbp": "Held payment to a non-client at or above this (GBP) needs an invoice (payments_fx)", "own_account_rfi_multiple": "Own-account money at this multiple of profile or more needs an updated profile", "tm01_limit_multiple_business": "TM01: tolerated multiple of declared monthly turnover (businesses)", "tm01_limit_multiple_individual": "TM01: tolerated multiple of declared monthly income (individuals)", "tm02_min": "TM02: unexplained money in at or above this (GBP) keeps the alert open"}, "policy": {"bank": {"invoice_required_gbp": null, "own_account_rfi_multiple": 5.0, "tm01_limit_multiple_business": null, "tm01_limit_multiple_individual": null, "tm02_min": 2000.0}, "emoney": {"invoice_required_gbp": null, "own_account_rfi_multiple": 5.0, "tm01_limit_multiple_business": null, "tm01_limit_multiple_individual": null, "tm02_min": 2000.0}, "investment": {"invoice_required_gbp": null, "own_account_rfi_multiple": 5.0, "tm01_limit_multiple_business": null, "tm01_limit_multiple_individual": null, "tm02_min": 2000.0}, "payments_fx": {"invoice_required_gbp": 10000.0, "own_account_rfi_multiple": 5.0, "tm01_limit_multiple_business": null, "tm01_limit_multiple_individual": null, "tm02_min": 2000.0}}, "run": "#!/usr/bin/env python3\n\"\"\"Deterministic transaction-monitoring alert triage.\n\nusage: run <institution_folder> <output.jsonl> [--trace] [--policy=overrides.json]\n\nReads only the given institution folder. Writes only the output file and,\nwith --trace, <output>.trace.jsonl (a per-case knowledge graph + proof trace).\nNo network, no randomness, no LLM: identical inputs give byte-identical outputs.\n\"\"\"\nimport json, os, re, sys\nfrom datetime import date, datetime, timedelta\n\n# ----------------------------------------------------------------------------\n# Policy configuration (from each POLICY.md)\n# ----------------------------------------------------------------------------\nHIGH_RISK = {\"afghanistan\", \"belarus\", \"democratic republic of the congo\", \"haiti\", \"iran\", \"iraq\",\n             \"lebanon\", \"libya\", \"mali\", \"myanmar\", \"north korea\", \"russia\", \"somalia\", \"south sudan\",\n             \"syria\", \"venezuela\", \"yemen\"}\nOWN_ACCOUNT_RFI_MULTIPLE = 5.0           # all four SOPs\nPOLICY = {\n    \"bank\":        {\"tm02_min\": 2000.0, \"invoice_required_gbp\": None},\n    \"emoney\":      {\"tm02_min\": 2000.0, \"invoice_required_gbp\": None},\n    \"investment\":  {\"tm02_min\": 2000.0, \"invoice_required_gbp\": None},\n    \"payments_fx\": {\"tm02_min\": 2000.0, \"invoice_required_gbp\": 10000.0},\n}\n# Settings an approved policy change may override (run ... --policy=policy-overrides.json).\n# None = use the value the monitoring system put on the alert. Defaults leave outputs byte-identical.\nPOLICY_KEYS = {\n    \"tm02_min\": \"TM02: unexplained money in at or above this (GBP) keeps the alert open\",\n    \"invoice_required_gbp\": \"Held payment to a non-client at or above this (GBP) needs an invoice (payments_fx)\",\n    \"own_account_rfi_multiple\": \"Own-account money at this multiple of profile or more needs an updated profile\",\n    \"tm01_limit_multiple_individual\": \"TM01: tolerated multiple of declared monthly income (individuals)\",\n    \"tm01_limit_multiple_business\": \"TM01: tolerated multiple of declared monthly turnover (businesses)\",\n}\nfor _p in POLICY.values():\n    _p.setdefault(\"own_account_rfi_multiple\", OWN_ACCOUNT_RFI_MULTIPLE)\n    _p.setdefault(\"tm01_limit_multiple_individual\", None)\n    _p.setdefault(\"tm01_limit_multiple_business\", None)\n\n\ndef load_policy_overrides(path, inst):\n    \"\"\"Merge an approved override file into POLICY[inst]. Format (written by the viewer's Approve step):\n    {\"schema\": \"poligraph.policy-overrides/1\", \"institution\": \"<inst>\" (optional, else all),\n     \"overrides\": {\"<key>\": <number or null>, ...}, \"version\": n, \"approved_by\": \"...\", \"reason\": \"...\"}\"\"\"\n    with open(path, encoding=\"utf-8\") as fh:\n        doc = json.load(fh)\n    ov = doc.get(\"overrides\", doc)\n    target = doc.get(\"institution\")\n    if target and target != inst:\n        return {}\n    applied = {}\n    for k, v in sorted(ov.items()):\n        if k not in POLICY_KEYS:\n            raise ValueError(\"unknown policy key %r\" % k)\n        if v is not None and not isinstance(v, (int, float)):\n            raise ValueError(\"policy key %r must be a number or null\" % k)\n        POLICY.setdefault(inst, dict(POLICY[\"bank\"]))[k] = None if v is None else float(v)\n        applied[k] = v\n    return applied\nBOILERPLATE = {\"due_diligence_summary\", \"proof_of_address\", \"contact_note\"}\nVERDICT_OF = {\n    \"COLLECTION_DOCUMENTED\": \"CLOSE\", \"BUSINESS_RECORDS_RECONCILE\": \"CLOSE\", \"DOCUMENTED_EVENT\": \"CLOSE\",\n    \"INVOICE_MATCHES\": \"CLOSE\", \"OWN_ACCOUNT\": \"CLOSE\", \"GROUP_COMPANY\": \"CLOSE\",\n    \"THIRD_PARTY_DOCUMENTED\": \"CLOSE\", \"REFUND_OF_EARLIER_PAYMENT\": \"CLOSE\", \"RETURNING_CUSTOMER\": \"CLOSE\",\n    \"LIST_MATCH_DIFFERENT_PARTY\": \"CLOSE\", \"WITHIN_PROFILE\": \"CLOSE\",\n    \"RFI_PURPOSE_DOCUMENTS\": \"RFI\", \"RFI_BUSINESS_RECORDS\": \"RFI\", \"RFI_SOURCE_OF_FUNDS\": \"RFI\",\n    \"RFI_COUNTERPARTY_DETAILS\": \"RFI\", \"RFI_UPDATED_PROFILE\": \"RFI\",\n    \"ESC_MULE_ACTIVITY\": \"ESCALATE\", \"ESC_STRUCTURING\": \"ESCALATE\", \"ESC_UNEXPLAINED_FUNDS\": \"ESCALATE\",\n    \"ESC_PASS_THROUGH\": \"ESCALATE\", \"ESC_INVOICE_MISMATCH\": \"ESCALATE\", \"ESC_HIGH_RISK_CORRIDOR\": \"ESCALATE\",\n    \"ESC_ACCOUNT_MISUSE\": \"ESCALATE\", \"ESC_THIRD_PARTY_FUNDING\": \"ESCALATE\", \"ESC_EARLY_REDEMPTION\": \"ESCALATE\",\n    \"ESC_LISTED_PARTY\": \"ESCALATE\",\n}\n# Which close ground leads when several explain the case (most specific first)\nCLOSE_PRIORITY = [\"LIST_MATCH_DIFFERENT_PARTY\", \"RETURNING_CUSTOMER\", \"COLLECTION_DOCUMENTED\",\n                  \"BUSINESS_RECORDS_RECONCILE\", \"GROUP_COMPANY\", \"REFUND_OF_EARLIER_PAYMENT\", \"DOCUMENTED_EVENT\",\n                  \"INVOICE_MATCHES\", \"THIRD_PARTY_DOCUMENTED\", \"OWN_ACCOUNT\", \"WITHIN_PROFILE\"]\n# Document type -> close ground when its amounts reconcile to a transaction\nEXPLAIN_TYPES = {\n    \"solicitor_letter\": \"DOCUMENTED_EVENT\", \"insurer_letter\": \"DOCUMENTED_EVENT\",\n    \"settlement_letter\": \"DOCUMENTED_EVENT\", \"completion_statement\": \"DOCUMENTED_EVENT\",\n    \"vehicle_sale_receipt\": \"DOCUMENTED_EVENT\", \"sale_receipt\": \"DOCUMENTED_EVENT\",\n    \"deposit_return_letter\": \"DOCUMENTED_EVENT\", \"holding_deposit_receipt\": \"DOCUMENTED_EVENT\",\n    \"loan_agreement\": \"DOCUMENTED_EVENT\", \"redundancy_letter\": \"DOCUMENTED_EVENT\",\n    \"dealer_invoice\": \"INVOICE_MATCHES\", \"hospital_invoice\": \"INVOICE_MATCHES\", \"invoice\": \"INVOICE_MATCHES\",\n    \"supplier_invoice\": \"INVOICE_MATCHES\", \"receipt\": \"INVOICE_MATCHES\", \"contract_schedule\": \"INVOICE_MATCHES\",\n    \"venue_email\": \"REFUND_OF_EARLIER_PAYMENT\", \"credit_note\": \"REFUND_OF_EARLIER_PAYMENT\",\n    \"cancellation_confirmation\": \"REFUND_OF_EARLIER_PAYMENT\",\n    \"gift_letter\": \"THIRD_PARTY_DOCUMENTED\",\n    \"cash_collection_reports\": \"BUSINESS_RECORDS_RECONCILE\", \"cash_reconciliation\": \"BUSINESS_RECORDS_RECONCILE\",\n    \"takings_book\": \"BUSINESS_RECORDS_RECONCILE\", \"freight_invoices\": \"BUSINESS_RECORDS_RECONCILE\",\n    \"carrier_invoice\": \"BUSINESS_RECORDS_RECONCILE\", \"payment_file\": \"BUSINESS_RECORDS_RECONCILE\",\n}\nINVOICE_LIKE = {\"invoice\", \"supplier_invoice\", \"supplier_invoices\", \"dealer_invoice\", \"hospital_invoice\",\n                \"carrier_invoice\", \"freight_invoices\", \"contract_schedule\", \"supply_contract\", \"consulting_contract\",\n                \"purchase_order\", \"payment_file\", \"receipt\", \"credit_note\"}\nSUSPICION_WORDS = re.compile(r\"\\b(scam|fraud|freeze|mule|launder\\w*|crypto)\\b\", re.I)\nGENERIC_TOKENS = {\"ltd\", \"llp\", \"plc\", \"limited\", \"the\", \"and\", \"of\", \"client\", \"account\", \"co\", \"company\", \"group\",\n                  \"holdings\", \"estate\", \"payment\", \"transfer\", \"from\", \"to\", \"for\", \"bank\", \"refund\", \"booking\",\n                  \"inv\", \"ref\", \"sal\", \"srl\", \"fze\", \"bv\", \"gmbh\", \"trading\", \"services\", \"solicitors\", \"card\",\n                  \"settlement\", \"agreement\", \"deposit\", \"loan\", \"advance\", \"funding\", \"top\", \"up\"}\nMONTHS = {m: i for i, m in enumerate([\"january\", \"february\", \"march\", \"april\", \"may\", \"june\", \"july\", \"august\",\n                                       \"september\", \"october\", \"november\", \"december\"], 1)}\n\n# ----------------------------------------------------------------------------\n# Parsing helpers\n# ----------------------------------------------------------------------------\n# Pound amounts: \"£1,234.56\", \"GBP 1234.56\", \"1,234.56 GBP\", \"1,234 pounds\".\nMONEY_RE = re.compile(r\"(?:£|\\bGBP)\\s?(\\d[\\d,]*(?:\\.\\d{1,2})?)|\\b(\\d[\\d,]*(?:\\.\\d{1,2})?)\\s?(?:GBP|pounds?)\\b\", re.I)\nCUR = r\"(?:£|\\bGBP\\s?)\"  # currency marker used inside threshold-talk patterns\n# One shared date grammar: \"12 August 2026\", \"12th Aug 2026\", \"August 12, 2026\", \"2026-08-12\", \"12/08/2026\" (UK d/m).\n_MON = (r\"(?:January|February|March|April|May|June|July|August|September|October|November|December|\"\n        r\"Jan|Feb|Mar|Apr|Jun|Jul|Aug|Sept|Sep|Oct|Nov|Dec)\\.?\")\nDATE_RE = re.compile(r\"\\b(?:(?P<d1>\\d{1,2})(?:st|nd|rd|th)?\\s+(?:of\\s+)?(?P<m1>\" + _MON + r\"),?\\s+(?P<y1>\\d{4})\"\n                     r\"|(?P<m2>\" + _MON + r\")\\s+(?P<d2>\\d{1,2})(?:st|nd|rd|th)?,?\\s+(?P<y2>\\d{4})\"\n                     r\"|(?P<y3>\\d{4})-(?P<m3>\\d{1,2})-(?P<d3>\\d{1,2})\"\n                     r\"|(?P<d4>\\d{1,2})/(?P<m4>\\d{1,2})/(?P<y4>\\d{4}))\\b\", re.I)\nMONTH_YEAR_RE = re.compile(r\"\\b(?P<m>\" + _MON + r\")\\s+(?P<y>\\d{4})\\b|\\b(?P<y2>\\d{4})-(?P<m2>\\d{1,2})\\b\", re.I)\n\n\ndef money(s):\n    out = []\n    for mm in MONEY_RE.finditer(s or \"\"):\n        m = mm.group(1) or mm.group(2)\n        try:\n            out.append(round(float(m.replace(\",\", \"\")), 2))\n        except ValueError:\n            pass\n    return out\n\n\ndef fmt(x):\n    return \"£{:,.2f}\".format(x)\n\n\ndef month_num(m):\n    \"\"\"'August' / 'Aug' / 'Sept.' / '8' -> 8.\"\"\"\n    m = str(m).lower().rstrip(\".\")\n    if m.isdigit():\n        return int(m)\n    for k, v in MONTHS.items():\n        if k.startswith(m[:3]):\n            return v\n    return None\n\n\ndef match_date(m):\n    \"\"\"Date from a DATE_RE match (None if the numbers are not a real date).\"\"\"\n    g = m.groupdict()\n    for i in \"1234\":\n        if g.get(\"y\" + i):\n            try:\n                return date(int(g[\"y\" + i]), month_num(g[\"m\" + i]), int(g[\"d\" + i]))\n            except (TypeError, ValueError):\n                return None\n    return None\n\n\ndef pdate(s):\n    \"\"\"Parse the first real date in s ('12 August 2026', 'Aug 12, 2026', ISO '2026-08-12...', '12/08/2026').\"\"\"\n    if not s:\n        return None\n    s = str(s)\n    m = re.match(r\"(\\d{4})-(\\d{2})-(\\d{2})\", s)\n    if m:\n        return date(int(m.group(1)), int(m.group(2)), int(m.group(3)))\n    for m in DATE_RE.finditer(s):\n        d = match_date(m)\n        if d:\n            return d\n    return None\n\n\ndef month_year(s):\n    \"\"\"(month, year) stated in s: a full date, 'February 1959', 'Feb 1959' or '1959-02'.\"\"\"\n    d = pdate(s)\n    if d:\n        return d.month, d.year\n    m = MONTH_YEAR_RE.search(s or \"\")\n    if not m:\n        return None\n    mo = month_num(m.group(\"m\") or m.group(\"m2\"))\n    return (mo, int(m.group(\"y\") or m.group(\"y2\"))) if mo and 1 <= mo <= 12 else None\n\n\ndef dtxt(d):\n    return \"{} {} {}\".format(d.day, [k for k, v in MONTHS.items() if v == d.month][0].capitalize(), d.year) if d else \"?\"\n\n\ndef norm(s):\n    s = (s or \"\").lower()\n    s = re.sub(r\"[^a-z0-9& ]+\", \" \", s)\n    if \"limited\" in s:\n        s = re.sub(r\"\\blimited\\b\", \"ltd\", s)\n    return re.sub(r\"\\s+\", \" \", s).strip()\n\n\ndef tokens(s):\n    return [t for t in norm(s).split() if len(t) >= 4 and t not in GENERIC_TOKENS and not t.isdigit()]\n\n\ndef acct_key(s):\n    \"\"\"Normalise an account reference to its last 4 digits ('IBAN ending 5416', '96-25-05 28236724').\"\"\"\n    if not s:\n        return None\n    d = re.findall(r\"\\d+\", str(s))\n    if not d:\n        return None\n    return d[-1][-4:]\n\n\ndef surname(name):\n    p = norm(name).split()\n    return p[-1] if p else \"\"\n\n\n# Alternative field labels -> the label the rules read (only filled when the canonical label is absent).\nFIELD_ALIASES = {\"remit to\": \"pay to\", \"payee\": \"pay to\", \"beneficiary\": \"pay to\", \"pay\": \"pay to\",\n                 \"total\": \"amount\", \"invoice total\": \"amount\", \"total due\": \"amount due\", \"balance due\": \"amount due\",\n                 \"amount payable\": \"amount due\",\n                 \"date of incorporation\": \"incorporated\", \"incorporated on\": \"incorporated\"}\n\n\ndef parse_fields(text):\n    f = {}\n    for m in re.finditer(r\"^\\*\\*([^*]+?):\\*\\*\\s*(.*)$\", text, re.M):\n        k = m.group(1).strip().lower()\n        if k not in f:\n            f[k] = m.group(2).strip()\n    for k, canon in FIELD_ALIASES.items():\n        if k in f and canon not in f:\n            f[canon] = f[k]\n    return f\n\n\ndef parse_tables(text):\n    tables, cur, header = [], None, None\n    for line in text.split(\"\\n\"):\n        line = line.strip()\n        if line.startswith(\"|\") and line.endswith(\"|\"):\n            cells = [c.strip() for c in line.strip(\"|\").split(\"|\")]\n            if header is None:\n                header, cur = [c.lower() for c in cells], []\n            elif all(re.fullmatch(r\":?-{2,}:?\", c) for c in cells if c):\n                continue\n            else:\n                row = {header[i] if i < len(header) else str(i): cells[i] for i in range(len(cells))}\n                cur.append(row)\n        else:\n            if header is not None:\n                tables.append(cur)\n            header, cur = None, None\n    if header is not None:\n        tables.append(cur)\n    return tables\n\n\n# ----------------------------------------------------------------------------\n# Normalisation layer\n# Every evidence document, and every free-text string in the jsonl inputs, goes through normalise() before\n# any rule reads it. Each step is a fixed, ordered table, so the output is deterministic. Text that is\n# already canonical comes back unchanged, so canonical inputs give byte-identical results.\n#   1. characters : non-breaking/thin spaces -> space; curly double quotes -> \"; en/em dash -> -\n#   2. whitespace : tabs and runs of spaces inside a line -> one space; lines broken mid-sentence are rejoined\n#   3. money      : \"GBP 9680.13\", \"9,680.13 GBP\", \"9680.13 pounds\", \"£ 9680.13\"  -> \"£9,680.13\"\n#   4. dates      : \"2026-09-14\", \"14/09/2026\", \"14-09-2026\", \"14.09.2026\" (UK day-first), \"September 14, 2026\",\n#                   \"14th Sep 2026\", \"14th of September 2026\"                     -> \"14 September 2026\"\n#   5. labels     : field labels \"**Remit to:**\", \"**Payee:**\", \"**Balance due:**\", \"**Name on account:**\" ...\n#                   -> the label the rules read (FIELD_LABEL_SYNONYMS)\n#                   abbreviated label/table-header words \"Acct\", \"No.\", \"Ref.\", \"Dir.\", \"Co.\" -> full words\n#                   (LABEL_ABBREVIATIONS)\n#   6. entities   : company legal forms \"Limited\", \"Ltd.\", \"LIMITED\", \"P.L.C.\" -> \"Ltd\", \"plc\" (ENTITY_FORMS)\n#   7. phrases    : wording synonyms -> the wording the rules read (PHRASE_SYNONYMS)\n# ----------------------------------------------------------------------------\n_MONTH_NAMES = [\"January\", \"February\", \"March\", \"April\", \"May\", \"June\", \"July\", \"August\", \"September\", \"October\",\n                \"November\", \"December\"]\n_NMON = (r\"(?:January|February|March|April|May|June|July|August|September|October|November|December|\"\n         r\"Jan|Feb|Mar|Apr|Jun|Jul|Aug|Sept|Sep|Oct|Nov|Dec)\\.?\")\nCHAR_MAP = [(\"\\u00a0\", \" \"), (\"\\u2007\", \" \"), (\"\\u202f\", \" \"), (\"\\u2009\", \" \"), (\"\\t\", \" \"),\n            (\"\\u201c\", '\"'), (\"\\u201d\", '\"'), (\"\\u2013\", \"-\"), (\"\\u2014\", \"-\")]\nFIELD_LABEL_SYNONYMS = [  # (label as written, canonical label)\n    (\"remit to\", \"Pay to\"), (\"payee\", \"Pay to\"), (\"pay\", \"Pay to\"), (\"payable to\", \"Pay to\"),\n    (\"balance due\", \"Amount due\"), (\"total due\", \"Amount due\"), (\"amount payable\", \"Amount due\"),\n    (\"names on account\", \"Account holders\"), (\"name on account\", \"Account holder\"), (\"account holder names\", \"Account holders\"),\n    (\"account in the name of\", \"Account holder\"),\n    (\"name of account holder\", \"Account holder\"),\n    (\"date of incorporation\", \"Incorporated\"), (\"incorporated on\", \"Incorporated\"),\n    (\"dob\", \"Date of birth\"), (\"born\", \"Date of birth\"),\n]\nLABEL_ABBREVIATIONS = [  # abbreviated words inside field labels -> full word (applied before FIELD_LABEL_SYNONYMS)\n    (r\"\\bacct\\.?(?=[\\s:]|$)\", \"account\"), (r\"\\bno\\.(?=[\\s:]|$)\", \"number\"), (r\"\\bref\\.?(?=[\\s:]|$)\", \"reference\"),\n    (r\"\\bdir\\.(?=[\\s:]|$)\", \"director\"), (r\"\\bco\\.(?=[\\s:]|$)\", \"company\"),\n]\nENTITY_FORMS = [  # legal-form spellings of company names -> the form used in the transaction data\n    (r\"(?<=[A-Za-z.]) (?:Limited|LIMITED|Ltd\\.|LTD\\.?)(?=[\\s,.;:)'\\u2019]|$)\", \" Ltd\"),\n    (r\"(?<=[A-Za-z]) (?:Public Limited Company|P\\.L\\.C\\.|PLC)(?=[\\s,.;:)]|$)\", \" plc\"),\n    (r\"(?<=[A-Za-z]) (?:Limited Liability Partnership|L\\.L\\.P\\.)(?=[\\s,.;:)]|$)\", \" LLP\"),\n]\nPHRASE_SYNONYMS = [  # (regex, canonical wording); matched case-insensitively, first letter's case kept\n    (r\"\\bin the name of\\b\", \"held by\"),\n    (r\"\\bstepped down\\b\", \"resigned\"),\n    (r\"\\bacct\\.?(?= )\", \"account\"),\n    (r\"\\bceased to be (?:a )?director\\b\", \"resigned as director\"),\n    (r\"\\b(\\d+(?:\\.\\d+)?) ?(?:per ?cent|percent|pct)\\b\", r\"\\1%\"),\n]\n_DATE_FIXES = [\n    (re.compile(r\"\\b(\\d{4})-(\\d{1,2})-(\\d{1,2})\\b\"), \"ymd\"),\n    (re.compile(r\"\\b(\\d{1,2})[/.-](\\d{1,2})[/.-](\\d{4})\\b\"), \"dmy\"),\n    (re.compile(r\"\\b(\" + _NMON + r\")\\s+(\\d{1,2})(?:st|nd|rd|th)?,?\\s+(\\d{4})\\b\", re.I), \"mdy\"),\n    (re.compile(r\"\\b(\\d{1,2})(?:st|nd|rd|th)?\\s+(?:of\\s+)?(\" + _NMON + r\"),?\\s+(\\d{4})\\b\", re.I), \"dMy\"),\n    (re.compile(r\"\\b(\\d{1,2})(?:st|nd|rd|th)\\s+(?:of\\s+)?(\" + _NMON + r\")(?![a-z])\", re.I), \"dM\"),\n]\n\n\ndef _month(tok):\n    t = str(tok).lower().rstrip(\".\")\n    if t.isdigit():\n        n = int(t)\n        return _MONTH_NAMES[n - 1] if 1 <= n <= 12 else None\n    for m in _MONTH_NAMES:\n        if m.lower().startswith(t[:3]):\n            return m\n    return None\n\n\ndef _date_sub(kind):\n    def f(m):\n        g = m.groups()\n        if kind == \"ymd\":\n            y, mo, d = g\n        elif kind == \"dmy\":\n            d, mo, y = g\n        elif kind == \"mdy\":\n            mo, d, y = g\n        elif kind == \"dMy\":\n            d, mo, y = g\n        else:\n            d, mo, y = g[0], g[1], None\n        name = _month(mo)\n        try:\n            if not name or not 1 <= int(d) <= 31 or (y and date(int(y), _MONTH_NAMES.index(name) + 1, int(d)) is None):\n                return m.group(0)\n        except ValueError:\n            return m.group(0)\n        return \"%d %s %s\" % (int(d), name, y) if y else \"%d %s\" % (int(d), name)\n    return f\n\n\ndef _canon_amount(num):\n    num = num.replace(\",\", \"\")\n    ip, _, dp = num.partition(\".\")\n    if not ip.isdigit():\n        return None\n    return \"£\" + \"{:,}\".format(int(ip)) + (\".\" + dp if dp else \"\")\n\n\ndef _money_sub(m):\n    c = _canon_amount(m.group(1))\n    return c if c else m.group(0)\n\n\n_MONEY_FIXES = [\n    re.compile(r\"(?<![\\w£])(\\d[\\d,]*(?:\\.\\d{1,2})?)\\s?(?:GBP|pounds sterling|pounds|pound|sterling)\\b\", re.I),\n    re.compile(r\"\\b(?:GBP|STG|sterling)\\s?£?\\s?(\\d[\\d,]*(?:\\.\\d{1,2})?)(?![\\d])\", re.I),\n    re.compile(r\"£\\s?(\\d[\\d,]*(?:\\.\\d{1,2})?)(?![\\d])\"),\n]\n_BLOCK_START = re.compile(r\"^\\s*(?:\\||#|\\*\\*|[-*+] |\\d+[.)] |>)\")\n\n\ndef _keep_case(repl):\n    def f(m):\n        r = m.expand(repl)\n        return r[:1].upper() + r[1:] if m.group(0)[:1].isupper() else r\n    return f\n\n\n_LABEL_ABBR_RX = [(re.compile(rx, re.I), full) for rx, full in LABEL_ABBREVIATIONS]\n_ENTITY_RX = [(re.compile(rx), repl) for rx, repl in ENTITY_FORMS]\n_FIELD_SYN = {src: canon for src, canon in FIELD_LABEL_SYNONYMS}\n_FIELD_SYN_RX = re.compile(r\"^\\*\\*(\" + \"|\".join(re.escape(k) for k, _ in FIELD_LABEL_SYNONYMS) + r\"):\\*\\*\", re.M | re.I)\n_PHRASE_RX = [(re.compile(rx, re.I), _keep_case(repl)) for rx, repl in PHRASE_SYNONYMS]\n_DATE_RX = [(rx, _date_sub(kind)) for rx, kind in _DATE_FIXES]\n_SPACES_RX = re.compile(r\"(?<=\\S) {2,}(?=\\S)\")\n_LINE_END_RX = re.compile(r\"[.!?:;|\\\")\\u2019]$\")\n_FIELD_LABEL_RX = re.compile(r\"^\\*\\*([^*\\n]+?):\\*\\*\", re.M)\n_TABLE_HEAD_RX = re.compile(r\"^(\\|.*\\|)[ ]*\\n(?=\\|[\\s:|-]*-{3,}[\\s:|-]*\\|?[ ]*$)\", re.M)\n_RAW_SPECIAL_RX = re.compile(\"[\\u00a0\\u2007\\u202f\\u2009\\t\\u201c\\u201d\\u2013\\u2014]|\\\\\\\\u(?:00a0|2007|202f|2009|201c|201d|2013|2014)|\\\\\\\\t|  \")\n\n\n_RAW_SPECIALS = (\"\\u00a0\", \"\\u2007\", \"\\u202f\", \"\\u2009\", \"\\t\", \"\\u201c\", \"\\u201d\", \"\\u2013\", \"\\u2014\", \"\\\\u00a0\",\n                 \"\\\\u2007\", \"\\\\u202f\", \"\\\\u2009\", \"\\\\u201c\", \"\\\\u201d\", \"\\\\u2013\", \"\\\\u2014\", \"\\\\t\", \"  \")\n_MONEY_HINTS = (\"gbp\", \"pound\", \"sterling\", \"stg\", \"£ \")\n\n\ndef _expand_label(lbl):\n    low = lbl.lower()\n    if \".\" not in lbl and \"acct\" not in low and \"ref\" not in low:\n        return lbl\n    new = lbl\n    for rx, full in _LABEL_ABBR_RX:\n        new = rx.sub(full, new)\n    if new == lbl:\n        return lbl\n    return new[:1].upper() + new[1:]\n\n\ndef normalise(text):\n    \"\"\"Canonicalise free text before the rules read it (see the table above). Idempotent and deterministic.\"\"\"\n    if not text:\n        return text\n    for a, b in CHAR_MAP:\n        text = text.replace(a, b)\n    lines = [_SPACES_RX.sub(\" \", ln.rstrip()) if \"  \" in ln else ln.rstrip() for ln in text.split(\"\\n\")]\n    out = []\n    for ln in lines:\n        if (out and out[-1].strip() and ln.strip() and ln.lstrip()[:1].islower() and not _BLOCK_START.match(ln)\n                and not _BLOCK_START.match(out[-1]) and not _LINE_END_RX.search(out[-1])):\n            out[-1] = out[-1] + \" \" + ln.strip()\n        else:\n            out.append(ln)\n    text = \"\\n\".join(out)\n    low = text.lower()\n    for i, rx in enumerate(_MONEY_FIXES):\n        if i < 2 and not any(h in low for h in _MONEY_HINTS):\n            continue\n        text = rx.sub(_money_sub, text)\n    for rx, fn in _DATE_RX:\n        text = rx.sub(fn, text)\n    text = _FIELD_LABEL_RX.sub(lambda m: \"**%s:**\" % _expand_label(m.group(1)), text)\n    text = _TABLE_HEAD_RX.sub(  # markdown table header row\n        lambda m: \"|\".join(c.replace(c.strip(), _expand_label(c.strip())) if c.strip() else c\n                           for c in m.group(1).split(\"|\")) + \"\\n\", text)\n    for rx, repl in _ENTITY_RX:\n        text = rx.sub(repl, text)\n    text = _FIELD_SYN_RX.sub(lambda m: \"**%s:**\" % _FIELD_SYN[m.group(1).lower()], text)\n    for rx, fn in _PHRASE_RX:\n        text = rx.sub(fn, text)\n    return text\n\n\ndef normalise_record(rec):\n    \"\"\"Light normalisation for jsonl string values (characters and whitespace only; ids and amounts untouched).\"\"\"\n    if isinstance(rec, dict):\n        return {k: normalise_record(v) for k, v in rec.items()}\n    if isinstance(rec, list):\n        return [normalise_record(v) for v in rec]\n    if isinstance(rec, str):\n        for a, b in CHAR_MAP:\n            rec = rec.replace(a, b)\n        return re.sub(r\" {2,}\", \" \", rec).strip() if \"  \" in rec or rec != rec.strip() else rec\n    return rec\n\n\nclass Doc(object):\n    def __init__(self, meta, text):\n        self.id = meta[\"doc_id\"]\n        self.type = meta.get(\"type\") or \"\"\n        self.title = meta.get(\"title\") or \"\"\n        self.dated = pdate(meta.get(\"dated\"))\n        text = normalise(text)\n        self.text = text\n        self.body = re.sub(r\"^# .*$|^\\*\\*Document ID:\\*\\*.*$|^\\*\\*Dated:\\*\\*.*$\", \"\", text, flags=re.M)\n        self.fields = parse_fields(text)\n        self.tables = parse_tables(text)\n        self.amounts = money(self.body)\n        self.ntext = norm(self.title + \" \" + self.body)\n\n\n# ----------------------------------------------------------------------------\n# Loading (only from the given institution folder)\n# ----------------------------------------------------------------------------\ndef read_jsonl(path):\n    out = []\n    if not os.path.exists(path):\n        return out\n    with open(path, encoding=\"utf-8\") as fh:\n        for line in fh:\n            line = line.strip()\n            if line:\n                rec = json.loads(line)\n                special = not line.replace(\"£\", \"\").replace(\"\\u2019\", \"\").isascii() or \"\\\\u\" in line or \"\\\\t\" in line or \"  \" in line\n                out.append(normalise_record(rec) if special and any(c in line for c in _RAW_SPECIALS) else rec)\n    return out\n\n\nclass World(object):\n    def __init__(self, folder):\n        self.folder = folder\n        self.inst = os.path.basename(os.path.normpath(folder))\n        self.cases = read_jsonl(os.path.join(folder, \"cases.jsonl\"))\n        inst = [c.get(\"institution\") for c in self.cases if c.get(\"institution\") in POLICY]\n        if inst:\n            self.inst = inst[0]\n        else:\n            for k in POLICY:\n                if k in folder.lower():\n                    self.inst = k\n        self.alerts = {a[\"alert_id\"]: a for a in read_jsonl(os.path.join(folder, \"alerts.jsonl\"))}\n        self.customers = {c[\"customer_id\"]: c for c in read_jsonl(os.path.join(folder, \"customers.jsonl\"))}\n        self.txns, self.txns_by_cust = {}, {}\n        for t in read_jsonl(os.path.join(folder, \"transactions.jsonl\")):\n            self.txns[t[\"transaction_id\"]] = t\n            self.txns_by_cust.setdefault(t[\"customer_id\"], []).append(t)\n        for v in self.txns_by_cust.values():\n            v.sort(key=lambda t: (t.get(\"booked_at\") or \"\", t[\"transaction_id\"]))\n        self.docs_meta = {}\n        for e in read_jsonl(os.path.join(folder, \"evidence.jsonl\")):\n            self.docs_meta.setdefault(e[\"customer_id\"], []).append(e)\n        self.reviews = {}\n        for r in read_jsonl(os.path.join(folder, \"previous_reviews.jsonl\")):\n            self.reviews.setdefault(r[\"customer_id\"], []).append(r)\n        self.listed = {r[\"entry_id\"]: r for r in read_jsonl(os.path.join(folder, \"internal_list.jsonl\"))}\n\n    def docs_for(self, cid):\n        out = []\n        for m in sorted(self.docs_meta.get(cid, []), key=lambda e: e[\"doc_id\"]):\n            p = os.path.join(self.folder, m.get(\"file\") or (\"evidence/%s.md\" % m[\"doc_id\"]))\n            try:\n                with open(p, encoding=\"utf-8\") as fh:\n                    txt = fh.read()\n            except OSError:\n                txt = \"\"\n            out.append(Doc(m, txt))\n        return out\n\n\n# ----------------------------------------------------------------------------\n# Case context, facts and proof trace\n# ----------------------------------------------------------------------------\nclass Case(object):\n    def __init__(self, world, case):\n        self.w = world\n        self.inst = world.inst\n        self.pol = POLICY.get(world.inst, POLICY[\"bank\"])\n        self.c = case\n        self.id = case[\"case_id\"]\n        self.cust = world.customers.get(case[\"customer_id\"], {\"customer_id\": case[\"customer_id\"], \"name\": \"\",\n                                                               \"declared\": {}, \"kind\": \"individual\"})\n        self.cname = self.cust.get(\"name\") or \"\"\n        self.alerts = [world.alerts[a] for a in case.get(\"alert_ids\", []) if a in world.alerts]\n        self.rules = sorted(set(a[\"rule_id\"] for a in self.alerts))\n        self.all_txns = world.txns_by_cust.get(case[\"customer_id\"], [])\n        self.tx = {t[\"transaction_id\"]: t for t in self.all_txns}\n        self.alerted = []\n        for a in self.alerts:\n            for t in a.get(\"transaction_ids\", []):\n                if t in self.tx and t not in self.alerted:\n                    self.alerted.append(t)\n        self.held = case.get(\"held_payment_id\")\n        rw = case.get(\"review_window\") or {}\n        self.wfrom, self.wto = pdate(rw.get(\"from\")), pdate(rw.get(\"to\"))\n        self.docs = world.docs_for(case[\"customer_id\"])\n        self.sig_docs = [d for d in self.docs if d.type not in BOILERPLATE]\n        self.reviews = sorted(world.reviews.get(case[\"customer_id\"], []), key=lambda r: r[\"review_id\"])\n        self.valid_ids = set([self.id] + [a[\"alert_id\"] for a in self.alerts] + list(self.tx) + [d.id for d in self.docs]\n                             + [r[\"review_id\"] for r in self.reviews] + [case[\"customer_id\"]])\n        self.list_entries = {}\n        for a in self.alerts:\n            le = (a.get(\"measured\") or {}).get(\"list_entry\")\n            if le and le in world.listed:\n                self.list_entries[le] = world.listed[le]\n                self.valid_ids.add(le)\n        # proof trace\n        self.facts, self.firings, self.edges = [], [], []\n\n    # --- trace helpers -----------------------------------------------------\n    def fact(self, kind, sources, **val):\n        f = {\"id\": \"F%d\" % (len(self.facts) + 1), \"kind\": kind, \"sources\": sorted(set(s for s in sources if s))}\n        f.update(val)\n        self.facts.append(f)\n        return f[\"id\"]\n\n    def edge(self, src, dst, rel):\n        e = (src, dst, rel)\n        if src and dst and e not in self.edges:\n            self.edges.append(e)\n\n    def fire(self, rule, outcome, facts, **extra):\n        r = {\"rule\": rule, \"outcome\": outcome, \"facts\": list(facts)}\n        r.update(extra)\n        self.firings.append(r)\n\n    # --- convenience ---------------------------------------------------------\n    def of_type(self, *types):\n        return [d for d in self.sig_docs if d.type in types]\n\n    def alerts_of(self, rule):\n        return [a for a in self.alerts if a[\"rule_id\"] == rule]\n\n    def t(self, tid):\n        return self.tx.get(tid)\n\n    def window_txns(self, before_days=45):\n        lo = (self.wfrom - timedelta(days=before_days)) if self.wfrom else None\n        out = []\n        for t in self.all_txns:\n            d = pdate(t.get(\"booked_at\"))\n            if lo and d and d < lo:\n                continue\n            if self.wto and d and d > self.wto + timedelta(days=1):\n                continue\n            out.append(t)\n        return out\n\n    def is_self(self, name):\n        return bool(name) and norm(name) == norm(self.cname)\n\n    def profile_explained(self, t):\n        \"\"\"Activity the declared profile itself explains: salary from the declared employer, card-acquirer\n        settlements for a business, and small own-name top-ups.\"\"\"\n        ref = (t.get(\"reference\") or \"\").upper()\n        cp = t.get(\"counterparty_name\") or \"\"\n        emp = self.cust.get(\"employer\") or \"\"\n        if t[\"direction\"] == \"in\" and (ref.startswith(\"SALARY\") or (emp and norm(cp) == norm(emp))):\n            return \"salary from declared employer\"\n        if t[\"direction\"] == \"in\" and ref == \"CARD SETTLEMENT\" and self.cust.get(\"kind\") == \"business\":\n            return \"card takings settlement\"\n        if t[\"direction\"] == \"in\" and self.is_self(cp) and not t.get(\"counterparty_account\") and t[\"amount_gbp\"] < 1000:\n            return \"small own-name top-up\"\n        if self.inst == \"payments_fx\" and t[\"direction\"] == \"in\" and self.is_self(cp):\n            return \"funding from the client's own account (a declared payment method)\"\n        if ref == \"MONTHLY CONTRIBUTION\" and t[\"amount_gbp\"] < 2500:\n            return \"regular monthly contribution\"\n        return None\n\n\ndef party_match(t, d):\n    \"\"\"Does document d refer to transaction t's counterparty (name/reference tokens or account digits)?\"\"\"\n    if (t.get(\"channel\") or \"\").startswith(\"cash\"):\n        return True\n    toks = tokens((t.get(\"counterparty_name\") or \"\") + \" \" + (t.get(\"reference\") or \"\"))\n    if any(re.search(r\"\\b%s\\b\" % re.escape(x), d.ntext) for x in toks):\n        return True\n    k = acct_key(t.get(\"counterparty_account\"))\n    if k and re.search(r\"\\b\\d*%s\\b\" % k, d.body):\n        return True\n    return False\n\n\ndef amount_in(t, d, tol=0.01):\n    for a in d.amounts:\n        if abs(a - t[\"amount_gbp\"]) <= tol or (t.get(\"amount\") is not None and abs(a - t[\"amount\"]) <= tol\n                                                and (t.get(\"currency\") or \"GBP\") == \"GBP\"):\n            return True\n    return False\n\n\n# ----------------------------------------------------------------------------\n# Suspicion rules (any one -> ESCALATE). Each returns a Finding or None.\n# ----------------------------------------------------------------------------\nclass Finding(object):\n    def __init__(self, code, rule, reason, evidence, facts=()):\n        self.code, self.rule, self.reason, self.evidence, self.facts = code, rule, reason, list(evidence), list(facts)\n\n\ndef in_txns(cs, ids=None):\n    ids = ids if ids is not None else cs.alerted\n    return [cs.t(i) for i in ids if cs.t(i) and cs.t(i)[\"direction\"] == \"in\"]\n\n\ndef out_txns(cs, ids=None):\n    ids = ids if ids is not None else cs.alerted\n    return [cs.t(i) for i in ids if cs.t(i) and cs.t(i)[\"direction\"] == \"out\"]\n\n\ndef s_fraud_reports(cs):\n    reps = cs.of_type(\"sending_bank_fraud_report\")\n    hits, tids, fids = [], [], []\n    for d in reps:\n        m = re.search(r\"(?:our customer|customer,?)\\s+([A-Z][a-z]+(?: [A-Z][a-z'-]+)+)\\s+(?:sent|paid|transferred)\", d.body)\n        sender = m.group(1) if m else None\n        for t in cs.window_txns():\n            if t[\"direction\"] == \"in\" and sender and norm(t.get(\"counterparty_name\")) == norm(sender):\n                hits.append(d.id); tids.append(t[\"transaction_id\"])\n                fids.append(cs.fact(\"scam_report_sender_paid_customer\", [d.id, t[\"transaction_id\"]], sender=sender,\n                                    amount=t[\"amount_gbp\"]))\n                cs.edge(d.id, t[\"transaction_id\"], \"contradicts\")\n                break\n    if not hits:\n        return None\n    senders = sorted(set(cs.t(t)[\"counterparty_name\"] for t in tids))\n    total = sum(cs.t(t)[\"amount_gbp\"] for t in tids)\n    outs = [t for t in out_txns(cs) if not cs.profile_explained(t) and t[\"amount_gbp\"] >= 500]\n    onward = (\" The money was moved straight on, e.g. %s to %s on %s.\" % (\n        fmt(outs[0][\"amount_gbp\"]), outs[0][\"counterparty_name\"], dtxt(pdate(outs[0][\"booked_at\"])))) if outs else \" The funds have no credible source.\"\n    reason = (\"%d sending banks report authorised push payment scams on payments into this account (%s) from %s, \"\n              \"totalling %s.%s The account is receiving and passing on victims' money, which is mule activity.\" % (\n                  len(set(hits)), \", \".join(sorted(set(hits))), \", \".join(senders), fmt(total), onward))\n    ev = sorted(set(hits)) + tids + [t[\"transaction_id\"] for t in outs[:3]]\n    ev += [d.id for d in cs.of_type(\"device_export\", \"support_chat\")]\n    return Finding(\"ESC_MULE_ACTIVITY\", \"S1_scam_reports\", reason, ev, fids)\n\n\nMULE_CHAT = re.compile(r\"payments? assistant|crypto account|(?:keep|keeping|retain|retaining|take|taking) (?:\\d+|a|an?\\s\\w+)\\s?(?:%|per ?cent\\b|percent\\b|cut\\b)|send it on to the company|their clients pay\",\n                       re.I)\nTHIRD_PARTY_INVEST = re.compile(r\"(friends?|cousins?|people|relatives?|others?)\\b[^.]{0,80}\\binvest|\"\n                                r\"invest(?:ing)?\\b[^.]{0,40}\\b(for|through) (them|a few people|people|mine|others)|\"\n                                r\"invest for (a few |some )?(people|friends|others)\", re.I)\n\n\ndef chats(cs):\n    return cs.of_type(\"support_chat\")\n\n\ndef first_sentence(text, cap=110):\n    t = re.sub(r\"\\s+\", \" \", (text or \"\").strip())\n    m = re.match(r\"(.+?[.!?])(\\s|$)\", t)\n    t = m.group(1) if m else t\n    return t if len(t) <= cap else t[:cap].rsplit(\" \", 1)[0] + \"...\"\n\n\ndef customer_lines(d):\n    return \" \".join(m.group(1) for m in re.finditer(r\"^\\W*Customer\\W*?:\\W*\\s*(.*)$\", d.text, re.M))\n\n\ndef s_mule_chat(cs):\n    for d in chats(cs):\n        if MULE_CHAT.search(customer_lines(d)):\n            fid = cs.fact(\"customer_describes_money_mule_role\", [d.id], quote=MULE_CHAT.search(customer_lines(d)).group(0))\n            ins = [t for t in in_txns(cs) if not cs.profile_explained(t)]\n            reason = (\"In %s the customer says they receive other people's money and send it on for a remote 'employer' \"\n                      \"(\\\"%s\\\"). %d third-party payments totalling %s came in during the window and were paid out. \"\n                      \"This is money-mule activity.\" % (d.id, MULE_CHAT.search(customer_lines(d)).group(0),\n                                                        len(ins), fmt(sum(t[\"amount_gbp\"] for t in ins))))\n            return Finding(\"ESC_MULE_ACTIVITY\", \"S2_mule_role_chat\", reason, [d.id] + [t[\"transaction_id\"] for t in ins[:6]],\n                           [fid])\n    return None\n\n\ndef s_third_party_investing(cs):\n    if cs.inst != \"investment\" and \"TM08\" not in cs.rules:\n        return None\n    for d in chats(cs):\n        cl = customer_lines(d)\n        if THIRD_PARTY_INVEST.search(cl):\n            fid = cs.fact(\"customer_invests_for_third_parties\", [d.id], quote=cl[:160])\n            tm08 = cs.alerts_of(\"TM08\")\n            tm10 = cs.alerts_of(\"TM10\")\n            flows = [cs.t(t) for a in tm08 for t in a[\"transaction_ids\"] if cs.t(t)]\n            fl = \"; \".join(\"%s %s %s\" % (fmt(t[\"amount_gbp\"]), \"from\" if t[\"direction\"] == \"in\" else \"to\",\n                                         t[\"counterparty_name\"]) for t in flows[:3])\n            ev = [d.id] + [t[\"transaction_id\"] for t in flows]\n            if tm10:\n                m = tm10[0][\"measured\"]\n                ev += tm10[0][\"transaction_ids\"]\n                reason = (\"Units in %s bought for %s were sold back after %s days for %s and paid to a third party (%s). \"\n                          \"In %s the customer says they invest for other people, so the platform is being used to move \"\n                          \"money for others through quick fund round trips.\" % (\n                              m.get(\"fund\"), fmt(m.get(\"bought_gbp\", 0)), m.get(\"held_days\"), fmt(m.get(\"redeemed_gbp\", 0)),\n                              fl or \"see alert\", d.id))\n                return Finding(\"ESC_EARLY_REDEMPTION\", \"S3_third_party_investing\", reason, ev, [fid])\n            reason = (\"Third parties fund or receive money from this account (%s). In %s the customer says the money \"\n                      \"belongs to other people (\\\"%s\\\"), which is unrelated third-party funding, not the customer's \"\n                      \"own investment.\" % (fl or \"see alerts\", d.id, cl.strip()[:120]))\n            return Finding(\"ESC_THIRD_PARTY_FUNDING\", \"S3_third_party_investing\", reason, ev, [fid])\n    return None\n\n\nTHRESHOLD_TALK = re.compile(r\"aggregat|exempt|below (the )?\" + CUR + r\"?[\\d,]+|under \" + CUR + r\"?[\\d,]+|break(ing)? (down|up)|split|\"\n                            r\"stay(ing)? (under|below)|keep(ing)? (individual |each )?(amounts?|transactions?|payments?|\"\n                            r\"deposits?|top-?ups?) (below|under)\", re.I)\n\n\ndef s_structuring_note(cs):\n    for d in cs.of_type(\"staff_note\"):\n        m = THRESHOLD_TALK.search(d.body)\n        if m and re.search(CUR + r\"\\s?10?,?000|\\b10?,?000(?:\\.00)?\\s?(?:GBP|pounds?)\\b|threshold|report|identity|invoice|verification\", d.body, re.I):\n            fid = cs.fact(\"customer_asked_how_to_avoid_threshold\", [d.id], quote=m.group(0))\n            subj = [a for a in cs.alerts if a[\"rule_id\"] == \"TM03\"] or cs.alerts\n            m3 = subj[0].get(\"measured\") or {}\n            ids = subj[0][\"transaction_ids\"]\n            cnt = m3.get(\"count\") or m3.get(\"payments\") or len(ids)\n            reason = (\"%s alert: %s transactions just under the threshold, totalling %s. Staff note %s records that the \"\n                      \"customer asked whether keeping amounts under the limit avoids checks or reporting. \"\n                      \"Splitting to stay under a threshold is structuring%s.\" % (\n                          subj[0][\"rule_id\"], cnt, fmt(m3.get(\"total_gbp\") or sum(cs.t(i)[\"amount_gbp\"] for i in ids if cs.t(i))),\n                          d.id, \"; the documents on file do not remove that suspicion\" if\n                          [x for x in cs.sig_docs if x.type in INVOICE_LIKE or x.type == \"management_accounts\"] else \"\"))\n            ev = [d.id] + ids + [x.id for x in cs.sig_docs if x.type in INVOICE_LIKE or x.type == \"management_accounts\"]\n            return Finding(\"ESC_STRUCTURING\", \"S4_threshold_avoidance\", reason, ev, [fid])\n    return None\n\n\ndef register_status(d):\n    for m in re.finditer(r\"dissolved(?: on)?:?\\s+\", d.body, re.I):\n        md = DATE_RE.match(d.body, m.end())\n        if md and match_date(md):\n            return match_date(md)\n    return None\n\n\ndef reg_company(d):\n    c = d.fields.get(\"company\")\n    if c:\n        return c\n    m = re.search(r\"extract for (.+)$\", d.title)\n    return m.group(1).strip() if m else None\n\n\ndef s_dissolved_payer(cs):\n    for d in cs.of_type(\"company_register_extract\"):\n        dis = register_status(d)\n        comp = reg_company(d)\n        if not dis or not comp:\n            continue\n        ts = [t for t in cs.window_txns(10) if norm(t.get(\"counterparty_name\")) == norm(comp)\n              and pdate(t[\"booked_at\"]) and pdate(t[\"booked_at\"]) > dis]\n        if ts:\n            fid = cs.fact(\"payer_company_dissolved_before_payment\", [d.id] + [t[\"transaction_id\"] for t in ts],\n                          company=comp, dissolved_on=str(dis))\n            for t in ts:\n                cs.edge(d.id, t[\"transaction_id\"], \"contradicts\")\n            claim = \"\"\n            for c in chats(cs):\n                claim = \" The customer's explanation in %s (\\\"%s\\\") cannot be true of a dissolved company.\" % (\n                    c.id, first_sentence(customer_lines(c)))\n                break\n            outs = [t for t in out_txns(cs) if not cs.profile_explained(t) and t[\"amount_gbp\"] >= 1000]\n            onward = (\" The funds were moved on (%s to %s on %s), so they have no credible source.\" % (fmt(outs[0][\"amount_gbp\"]), outs[0][\"counterparty_name\"],\n                                                                     dtxt(pdate(outs[0][\"booked_at\"])))) if outs else \" The funds have no credible source.\"\n            reason = (\"%d payments totalling %s came from %s, which %s shows was dissolved on %s, before the money was \"\n                      \"sent.%s%s\" % (\n                          len(ts), fmt(sum(t[\"amount_gbp\"] for t in ts)), comp, d.id, dtxt(dis), claim, onward))\n            ev = [d.id] + [t[\"transaction_id\"] for t in ts] + [c.id for c in chats(cs)] + [t[\"transaction_id\"] for t in outs[:3]]\n            return Finding(\"ESC_UNEXPLAINED_FUNDS\", \"S5_dissolved_payer\", reason, ev, [fid])\n    return None\n\n\ndef officers(d):\n    names = []\n    for tb in d.tables:\n        for row in tb:\n            for k in (\"officer\", \"person\", \"person with significant control\", \"owner\"):\n                if k in row and row[k]:\n                    names.append(row[k])\n    return names\n\n\ndef incorporated(d):\n    v = d.fields.get(\"incorporated\")\n    return pdate(v) if v else None\n\n\ndef s_pass_through(cs):\n    if cs.cust.get(\"kind\") != \"business\":\n        return None\n    own = [d for d in cs.of_type(\"company_register_extract\") if norm(reg_company(d) or \"\") == norm(cs.cname)]\n    directors = set(norm(n) for d in own for n in officers(d))\n    if not directors:\n        return None\n    opened = pdate(cs.c.get(\"opened_at\")) or cs.wto\n    linked = []\n    for d in cs.of_type(\"company_register_extract\"):\n        comp = reg_company(d)\n        if not comp or norm(comp) == norm(cs.cname):\n            continue\n        inc = incorporated(d)\n        if inc and opened and (opened - inc).days <= 400 and directors & set(norm(n) for n in officers(d)):\n            linked.append((d, comp, inc))\n    if not linked:\n        return None\n    names = set(norm(c) for _, c, _ in linked)\n    outs = [t for t in cs.window_txns(10) if t[\"direction\"] == \"out\" and norm(t.get(\"counterparty_name\")) in names]\n    ins = [t for t in in_txns(cs) if not cs.profile_explained(t) and t[\"amount_gbp\"] >= 1000]\n    if not outs and not ins:\n        return None\n    fid = cs.fact(\"funds_routed_to_new_companies_of_same_director\", [d.id for d, _, _ in linked] +\n                  [t[\"transaction_id\"] for t in outs], director=sorted(directors)[0])\n    cover = \"\"\n    for d in cs.of_type(\"consulting_contract\"):\n        if d.amounts:\n            cover = (\" The only contract on file, %s, is for a %s fee; it does not explain %s of new receipts.\" % (\n                d.id, fmt(max(d.amounts)), fmt(sum(t[\"amount_gbp\"] for t in ins))))\n    dname = [n for d in own for n in officers(d)][0]\n    reason = (\"%s received %d payments totalling %s and paid money on to %s, companies set up in %s by its own director \"\n              \"%s (%s).%s Money is passing through to linked parties with no credible purpose.\" % (\n                  cs.cname, len(ins), fmt(sum(t[\"amount_gbp\"] for t in ins)), \" and \".join(sorted(c for _, c, _ in linked)),\n                  \" and \".join(sorted(set(str(i.year) for _, _, i in linked))), dname,\n                  \", \".join(sorted(d.id for d, _, _ in linked)), cover))\n    ev = [d.id for d, _, _ in linked] + [t[\"transaction_id\"] for t in outs] + [t[\"transaction_id\"] for t in ins[:6]] + \\\n         [d.id for d in cs.of_type(\"consulting_contract\")] + [d.id for d in own]\n    return Finding(\"ESC_PASS_THROUGH\", \"S6_pass_through_linked\", reason, ev, [fid])\n\n\ndef s_shared_device(cs):\n    for d in cs.of_type(\"device_export\"):\n        ids = sorted(set(re.findall(r\"\\b[A-Z]{2}-C\\d+\\b\", d.body)))\n        others = [i for i in ids if i != cs.c[\"customer_id\"]]\n        if len(ids) >= 2 and others and ({\"TM02\", \"TM04\"} & set(cs.rules)):\n            countries = \"\"\n            for tb in d.tables:\n                for row in tb:\n                    countries = row.get(\"login countries\", countries)\n            ins = [t for t in in_txns(cs) if not cs.profile_explained(t)]\n            fid = cs.fact(\"device_shared_with_other_customers\", [d.id], customers=ids, countries=countries)\n            reason = (\"Device export %s shows the device used on this account is also logged into by %d other customers \"\n                      \"(%s), with logins from %s. %d payments from different people totalling %s arrived and were paid out \"\n                      \"within 48 hours. Someone other than the customer appears to control the account.\" % (\n                          d.id, len(others), \", \".join(others), countries or \"abroad\", len(ins),\n                          fmt(sum(t[\"amount_gbp\"] for t in ins))))\n            return Finding(\"ESC_ACCOUNT_MISUSE\", \"S7_shared_device\", reason, [d.id] + [t[\"transaction_id\"] for t in ins[:6]], [fid])\n    return None\n\n\nSOURCE_CLASSES = [(\"gift\", r\"\\bgift|present from\"), (\"sale\", r\"\\bsell|\\bsold|selling|sale of\"),\n                  (\"loan\", r\"\\bloan|borrow\"), (\"savings\", r\"savings\"), (\"inheritance\", r\"inherit|estate|will\\b\"),\n                  (\"family support\", r\"family support|help my family|support for\")]\n\n\ndef claim_classes(text):\n    return set(k for k, p in SOURCE_CLASSES if re.search(p, text, re.I))\n\n\ndef s_inconsistent_story(cs):\n    cl = [(d, claim_classes(customer_lines(d))) for d in chats(cs)]\n    cl = [(d, c) for d, c in cl if c]\n    if len(cl) < 2:\n        return None\n    a, b = cl[0], cl[1]\n    if a[1] & b[1]:\n        return None\n    big_cash = [cs.t(t) for al in cs.alerts_of(\"TM05\") for t in al[\"transaction_ids\"] if cs.t(t)]\n    outs = [t for t in out_txns(cs) if not cs.profile_explained(t) and t[\"amount_gbp\"] >= 1000]\n    fid = cs.fact(\"customer_gives_conflicting_explanations\", [a[0].id, b[0].id],\n                  first=sorted(a[1]), second=sorted(b[1]))\n    cs.edge(a[0].id, b[0].id, \"contradicts\")\n    reason = (\"The customer gives conflicting accounts of the money: %s says %s, while %s says %s.%s%s \"\n              \"With no document behind either story, the funds have no credible explanation and were moved on.\" % (\n                  a[0].id, \"/\".join(sorted(a[1])), b[0].id, \"/\".join(sorted(b[1])),\n                  (\" Cash deposit %s of %s.\" % (big_cash[0][\"transaction_id\"], fmt(big_cash[0][\"amount_gbp\"]))) if big_cash else \"\",\n                  (\" %s was sent to %s (%s).\" % (fmt(outs[0][\"amount_gbp\"]), outs[0][\"counterparty_name\"],\n                                                 outs[0][\"counterparty_country\"])) if outs else \"\"))\n    ev = [a[0].id, b[0].id] + [t[\"transaction_id\"] for t in big_cash] + [t[\"transaction_id\"] for t in outs[:3]]\n    return Finding(\"ESC_UNEXPLAINED_FUNDS\", \"S8_conflicting_explanations\", reason, ev, [fid])\n\n\ndef s_corridor(cs):\n    tm06 = cs.alerts_of(\"TM06\")\n    if not tm06:\n        return None\n    ids = [t for a in tm06 for t in a[\"transaction_ids\"]]\n    country = (tm06[0].get(\"measured\") or {}).get(\"countries\") or \"\"\n    # staff note: client cannot explain the routing\n    for d in cs.of_type(\"staff_note\"):\n        if re.search(r\"unable|unwilling|evasive|declin|refus|could ?n[o']t|cannot|can't|failed to|not (able|provide|explain)|\"\n                     r\"no (clear |plausible |credible )?(reason|justification|explanation|rationale)\", d.body, re.I) and \\\n                re.search(r\"rout|lebanon|iraq|iran|syria|countr|abroad\", d.body, re.I):\n            fid = cs.fact(\"client_cannot_explain_corridor\", [d.id], country=country)\n            invs = [x for x in cs.of_type(\"supplier_invoices\", \"supplier_invoice\", \"invoice\")]\n            reason = (\"%s moved to or from %s, a higher-risk country the client did not declare. Staff note %s records that \"\n                      \"the director could not explain why the payments go to %s%s. The payments are unexplained.\" % (\n                          fmt(sum(cs.t(t)[\"amount_gbp\"] for t in ids if cs.t(t))), country, d.id, country,\n                          (\", and invoices %s describe services that do not fit a %s business\" % (\n                              \", \".join(x.id for x in invs), (cs.cust.get(\"business_activity\") or \"\").lower())) if invs else \"\"))\n            return Finding(\"ESC_HIGH_RISK_CORRIDOR\", \"S9_corridor_unexplained\", reason,\n                           [d.id] + ids + [x.id for x in invs], [fid])\n    outs = [cs.t(t) for t in ids if cs.t(t) and cs.t(t)[\"direction\"] == \"out\"]\n    people = [t for t in outs if t.get(\"counterparty_name\") and len(norm(t[\"counterparty_name\"]).split()) == 2\n              and not re.search(r\"ltd|llc|sal|bank|center|centre|hotel|hospital\", norm(t[\"counterparty_name\"]))]\n    strangers = [t for t in people if surname(t[\"counterparty_name\"]) != surname(cs.cname)]\n    tp_in = [t for t in in_txns(cs) if not cs.profile_explained(t) and not cs.is_self(t.get(\"counterparty_name\"))\n             and t[\"amount_gbp\"] >= 1000]\n    if len(set(norm(t[\"counterparty_name\"]) for t in strangers)) >= 2 and (tp_in or len(strangers) >= 3):\n        f = [c for c in chats(cs)]\n        fid = cs.fact(\"split_payments_to_unrelated_people_in_high_risk_country\", [t[\"transaction_id\"] for t in strangers]\n                      + [c.id for c in f], country=country)\n        reason = (\"%d payments totalling %s went to %d different people in %s, a higher-risk country the customer did not \"\n                  \"declare, none sharing the customer's surname%s.%s No document shows who they are, so the payments are \"\n                  \"unexplained.\" % (len(strangers), fmt(sum(t[\"amount_gbp\"] for t in strangers)),\n                                    len(set(norm(t[\"counterparty_name\"]) for t in strangers)), country,\n                                    (\", funded by %d transfers from unrelated people (%s)\" % (\n                                        len(tp_in), fmt(sum(t[\"amount_gbp\"] for t in tp_in)))) if tp_in else \"\",\n                                    (\" The customer's only explanation in %s is \\\"%s\\\".\" % (\n                                        f[0].id, first_sentence(customer_lines(f[0])))) if f else \"\"))\n        ev = [t[\"transaction_id\"] for t in strangers] + [t[\"transaction_id\"] for t in tp_in[:4]] + [c.id for c in f]\n        return Finding(\"ESC_HIGH_RISK_CORRIDOR\", \"S9_corridor_unexplained\", reason, ev, [fid])\n    return None\n\n\nRED_FLAG_GOODS = [(r\"mobile phone|handset|smartphone\", r\"phone|mobile|telecom\"),\n                  (r\"consultancy|consulting|market access|advisory\", r\"consult|advis|services\")]\n\n\ndef s_invoice_mismatch(cs):\n    biz = (cs.cust.get(\"business_activity\") or \"\")\n    if cs.cust.get(\"kind\") != \"business\" or not biz:\n        return None\n    for d in cs.of_type(\"supplier_invoices\", \"supplier_invoice\", \"invoice\"):\n        items = [row.get(\"goods\", \"\") for tb in d.tables for row in tb if row.get(\"goods\")]\n        if d.fields.get(\"goods\"):\n            items.append(d.fields[\"goods\"])\n        goods = \"; \".join(items)\n        for pat, ok in RED_FLAG_GOODS:\n            if re.search(pat, goods, re.I) and not re.search(ok, biz, re.I):\n                fid = cs.fact(\"invoice_goods_inconsistent_with_business\", [d.id], goods=goods[:120],\n                              business_activity=biz)\n                sup = (d.fields.get(\"supplier\") or \"\").split(\",\")[0].strip()\n                outs = [t for t in cs.window_txns(10) if t[\"direction\"] == \"out\" and not cs.is_self(t.get(\"counterparty_name\"))\n                        and ((sup and norm(t.get(\"counterparty_name\")) == norm(sup)) or amount_in(t, d))]\n                if not outs:\n                    outs = [t for t in cs.window_txns(10) if t[\"direction\"] == \"out\" and t[\"amount_gbp\"] >= 10000 and\n                            not cs.is_self(t.get(\"counterparty_name\"))][:3]\n                reason = (\"%s's declared business is \\\"%s\\\", but %s%s bills it for %s (%s in total). Those goods do not \"\n                          \"fit the business, so the invoice does not support %s. Invoices that do not match the client's \"\n                          \"trade are a red flag.\" % (\n                              cs.cname, biz, d.id, (\" from \" + sup) if sup else \"\", goods[:100],\n                              fmt(sum(d.amounts)) if d.amounts else \"\",\n                              (\"the payments out (\" + \"; \".join(describe_txn(t) for t in outs[:2]) + \")\") if outs\n                              else \"the alerted activity\"))\n                ev = [d.id] + [a[\"alert_id\"] for a in cs.alerts] + cs.alerted[:6] + [t[\"transaction_id\"] for t in outs]\n                return Finding(\"ESC_INVOICE_MISMATCH\", \"S10_invoice_goods_mismatch\", reason, ev, [fid])\n    return None\n\n\ndef s_payment_file_mule(cs):\n    for d in cs.of_type(\"payment_file\"):\n        rows = [r for tb in d.tables for r in tb if \"address\" in r]\n        if not rows:\n            continue\n        addr = {}\n        for r in rows:\n            addr.setdefault(norm(r[\"address\"]), []).append(r)\n        shared = {k: v for k, v in addr.items() if len(v) >= 2}\n        uk_pc = [r for r in rows if re.search(r\"\\b[A-Z]{1,2}\\d{1,2}[A-Z]? ?\\d[A-Z]{2}\\b\", r[\"address\"])\n                 and norm(r.get(\"country\")) not in (\"united kingdom\", \"uk\")]\n        if shared or len(uk_pc) >= 2:\n            fid = cs.fact(\"payees_share_addresses_inconsistent_with_country\", [d.id], shared_addresses=len(shared),\n                          uk_address_abroad=len(uk_pc))\n            tp = [cs.t(t) for a in cs.alerts_of(\"TM08\") for t in a[\"transaction_ids\"] if cs.t(t)]\n            k0 = sorted(shared)[0] if shared else None\n            reason = (\"Payment file %s lists %d payees; %d addresses are shared by several payees (e.g. %s) and %d payees \"\n                      \"said to be abroad have UK addresses.%s Many small payments to linked people funded by a third \"\n                      \"party indicate the account is passing on other people's money.\" % (\n                          d.id, len(rows), len(shared), (\", \".join(r[\"payee\"] for r in shared[k0][:3]) + \" at \" +\n                                                         shared[k0][0][\"address\"]) if k0 else \"-\", len(uk_pc),\n                          (\" The money came in from %s (%s), whose account is not the client's.\" % (\n                              tp[0][\"counterparty_name\"], fmt(tp[0][\"amount_gbp\"]))) if tp else \"\"))\n            ev = [d.id] + [t[\"transaction_id\"] for t in tp]\n            return Finding(\"ESC_MULE_ACTIVITY\", \"S11_payment_file_linked_payees\", reason, ev, [fid])\n    return None\n\n\nSUSPICION_RULES = [s_fraud_reports, s_mule_chat, s_structuring_note, s_dissolved_payer, s_pass_through,\n                   s_third_party_investing, s_payment_file_mule, s_shared_device, s_inconsistent_story, s_corridor,\n                   s_invoice_mismatch]\n\n\n# ----------------------------------------------------------------------------\n# Internal-list (TM22) resolution: cleared / confirmed / unsettled\n# ----------------------------------------------------------------------------\ndef rget(r, *keys):\n    \"\"\"Tolerant table-cell lookup: exact header first, then a header starting with the key.\"\"\"\n    for k in keys:\n        if r.get(k):\n            return r[k]\n    for k in keys:\n        for h, v in sorted(r.items()):\n            if h.startswith(k) and v:\n                return v\n    return \"\"\n\n\ndef dob_near(text, name):\n    \"\"\"Find a date of birth stated for `name` in free text ('born 17 February 1959', '(DOB: 8 June 1969)').\"\"\"\n    if not name:\n        return None\n    for m in re.finditer(re.escape(name), text, re.I):\n        win = text[m.end(): m.end() + 80]\n        for mm in re.finditer(r\"(?:born(?: on)?|DOB:?|date of birth:?)\\s*\", win, re.I):\n            md = DATE_RE.match(win, mm.end())\n            if md and match_date(md):\n                return match_date(md)\n    return None\n\n\ndef resolve_tm22(cs, a):\n    m = a.get(\"measured\") or {}\n    L = cs.list_entries.get(m.get(\"list_entry\"))\n    basis = (m.get(\"matched_on\") or \"\").lower()\n    tids = a.get(\"transaction_ids\", [])\n    t = cs.t(tids[0]) if tids else None\n    pay = pdate(t[\"booked_at\"]) if t else None\n    if not L:\n        return {\"status\": \"unsettled\", \"basis\": basis, \"docs\": [], \"note\": \"list entry not found\"}\n    lname, ldob = L.get(\"name\") or \"\", pdate(L.get(\"date_of_birth\"))\n    cs.edge(a[\"alert_id\"], L[\"entry_id\"], \"matches\")\n    res = {\"status\": \"unsettled\", \"basis\": basis, \"entry\": L[\"entry_id\"], \"lname\": lname, \"docs\": [], \"note\": \"\",\n           \"pay\": pay, \"txn\": t}\n    if \"officer\" in basis:\n        psc_rows, reg_rows = [], []\n        for d in cs.of_type(\"significant_control_register\"):\n            for tb in d.tables:\n                for r in tb:\n                    if norm(rget(r, \"person\", \"name\")) == norm(lname):\n                        psc_rows.append((d, r))\n        for d in cs.of_type(\"company_register_extract\"):\n            for tb in d.tables:\n                for r in tb:\n                    if norm(rget(r, \"officer\", \"name\")) == norm(lname):\n                        reg_rows.append((d, r))\n        # A different birth month/year on the register disproves identity\n        for d, r in reg_rows + psc_rows:\n            born = rget(r, \"born\", \"date of birth\", \"dob\")\n            mb = month_year(born or \"\")\n            if mb and ldob and (mb[1] != ldob.year or mb[0] != ldob.month):\n                fid = cs.fact(\"officer_birth_differs_from_list\", [d.id, L[\"entry_id\"]], register_born=born,\n                              list_dob=str(ldob))\n                cs.edge(d.id, L[\"entry_id\"], \"contradicts\")\n                res.update(status=\"cleared\", docs=[d.id], fact=fid,\n                           note=\"%s gives %s's birth as %s, but list entry %s has %s\" % (d.id, lname, born, L[\"entry_id\"],\n                                                                                      dtxt(ldob)))\n                return res\n        for d, r in psc_rows:\n            ceased = pdate(rget(r, \"ceased\"))\n            if pay and (ceased is None or ceased >= pay):\n                fid = cs.fact(\"listed_person_controlled_counterparty_at_payment\", [d.id, L[\"entry_id\"]] + tids,\n                              control=rget(r, \"control\", \"nature\"), ceased=str(ceased) if ceased else None, payment=str(pay))\n                cs.edge(d.id, L[\"entry_id\"], \"supports\")\n                regs = [x.id for x, _ in reg_rows]\n                for x, rr in reg_rows:\n                    rs = pdate(rget(rr, \"resigned\"))\n                    if rs and pay and rs <= pay:\n                        # the register's resignation date is overridden by continuing control on the PSC register\n                        cs.fact(\"officer_resigned_before_payment\", [x.id], resigned=str(rs), payment=str(pay))\n                        cs.edge(d.id, x.id, \"contradicts\")\n                res.update(status=\"confirmed\", docs=[d.id] + regs, fact=fid,\n                           note=(\"%s shows %s held \\\"%s\\\" in the company until %s, so they still controlled it when the \"\n                                 \"%s payment was made on %s\" % (d.id, lname, rget(r, \"control\", \"nature\"),\n                                                                dtxt(ceased) if ceased else \"now\",\n                                                                fmt(t[\"amount_gbp\"]) if t else \"\", dtxt(pay))))\n                return res\n        if psc_rows or reg_rows:\n            ended = all(pdate(rget(r, \"ceased\", \"resigned\")) and pay and\n                        pdate(rget(r, \"ceased\", \"resigned\")) < pay for _, r in psc_rows + reg_rows)\n            if ended and psc_rows:\n                d = psc_rows[0][0]\n                fid = cs.fact(\"listed_person_left_before_payment\", [d.id, L[\"entry_id\"]])\n                res.update(status=\"cleared\", docs=sorted(set(x.id for x, _ in psc_rows + reg_rows)), fact=fid,\n                           note=\"%s shows %s's control ended before the payment on %s\" % (d.id, lname, dtxt(pay)))\n                return res\n        res[\"note\"] = \"no register shows who controlled the counterparty at the time of payment\"\n        return res\n    if \"address\" in basis:\n        lunit = re.search(r\"\\bUnit \\w+\", (L.get(\"reason\") or \"\") + \" \" + (L.get(\"address\") or \"\"))\n        best = None\n        for d in cs.of_type(\"company_register_extract\", \"receipt\", \"invoice\"):\n            u = re.search(r\"\\bUnit \\w+\", d.body)\n            if u and (d.type != \"company_register_extract\" or norm(reg_company(d) or \"\") != norm(cs.cname)):\n                best = best or (d, u.group(0))\n                if d.type == \"company_register_extract\":\n                    best = (d, u.group(0))\n        if lunit and best and norm(best[1]) != norm(lunit.group(0)):\n            d, unit = best\n            fid = cs.fact(\"counterparty_address_differs_from_list\", [d.id, L[\"entry_id\"]], counterparty_unit=unit,\n                          list_unit=lunit.group(0))\n            cs.edge(d.id, L[\"entry_id\"], \"contradicts\")\n            others = [x.id for x in cs.of_type(\"company_register_extract\", \"receipt\") if x.id != d.id]\n            res.update(status=\"cleared\", docs=[d.id] + others, fact=fid,\n                       note=(\"list entry %s is %s, an %s linked to %s, while %s places %s at %s; the shared building is \"\n                             \"the only link\" % (L[\"entry_id\"], lname, L.get(\"kind\"), lunit.group(0), d.id,\n                                               t[\"counterparty_name\"] if t else \"the payee\", unit)))\n            return res\n        res[\"note\"] = \"nothing on file shows whether the payee at the matched address is the listed party\"\n        return res\n    # name (or anything else): look for a date of birth for the counterparty\n    cp = (t or {}).get(\"counterparty_name\") or lname\n    for d in cs.sig_docs:\n        dob = dob_near(d.text, cp) or dob_near(d.text, lname)\n        if dob and ldob:\n            if dob == ldob:\n                fid = cs.fact(\"counterparty_dob_equals_list_dob\", [d.id, L[\"entry_id\"]], dob=str(dob))\n                cs.edge(d.id, L[\"entry_id\"], \"supports\")\n                res.update(status=\"confirmed\", docs=[d.id], fact=fid,\n                           note=\"%s gives %s's date of birth as %s, the same as list entry %s\" % (d.id, cp, dtxt(dob),\n                                                                                                L[\"entry_id\"]))\n            else:\n                fid = cs.fact(\"counterparty_dob_differs_from_list\", [d.id, L[\"entry_id\"]], dob=str(dob), list_dob=str(ldob))\n                cs.edge(d.id, L[\"entry_id\"], \"contradicts\")\n                res.update(status=\"cleared\", docs=[d.id], fact=fid,\n                           note=\"%s gives %s's date of birth as %s, but list entry %s was born on %s\" % (\n                               d.id, cp, dtxt(dob), L[\"entry_id\"], dtxt(ldob)))\n            return res\n    for d in cs.of_type(\"company_register_extract\"):\n        for tb in d.tables:\n            for r in tb:\n                if norm(r.get(\"officer\", rget(r, \"person\", \"name\"))) == norm(lname) and rget(r, \"born\") and ldob:\n                    mb = month_year(rget(r, \"born\"))\n                    if mb and (mb[1] != ldob.year):\n                        res.update(status=\"cleared\", docs=[d.id], note=\"%s gives %s's birth as %s, list entry %s has %s\" % (\n                            d.id, lname, rget(r, \"born\"), L[\"entry_id\"], dtxt(ldob)))\n                        return res\n    res[\"note\"] = \"only the name matches; nothing on file gives %s's date of birth or address\" % cp\n    return res\n\n\n# ----------------------------------------------------------------------------\n# Explanation rules: each covers transactions with a document (accounting-style)\n# ----------------------------------------------------------------------------\nclass Expl(object):\n    def __init__(self, code, rule, docs, txns, note, onward=0.0):\n        self.code, self.rule, self.docs, self.txns, self.note, self.onward = code, rule, list(docs), list(txns), note, onward\n\n    def direction_in(self, cs):\n        return any((cs.t(t) or {}).get(\"direction\") == \"in\" for t in self.txns)\n\n\ndef statement_holders(d):\n    h = \"\"\n    for k in (\"account holder\", \"account holders\", \"name on account\", \"account name\", \"name of account holder\",\n              \"holder\", \"holders\", \"account in the name of\"):\n        if d.fields.get(k):\n            h = d.fields[k]\n            break\n    names = [x.strip() for x in re.split(r\",| and | & (?=\\S+ \\S)\", h) if x.strip()]\n    for m in re.finditer(r\"(?:held by|held in the name of|in the name of|registered to|belongs to|belonging to)\"\n                         r\" ([A-Z][\\w&' -]+?)(?:\\.|,|$)\", d.body, re.M):\n        names.append(m.group(1).strip())\n    if re.search(r\"held in (my|your) name|in your name\", d.body, re.I):\n        names.append(\"__self__\")\n    return names\n\n\ndef statement_keys(d):\n    keys = set()\n    for v in (d.fields.get(\"account\"),):\n        k = acct_key(v) if v and re.search(r\"\\d\", v) else None\n        if k:\n            keys.add(k)\n    for m in re.finditer(r\"(?:IBAN|account) ending (\\d{4})\", d.body):\n        keys.add(m.group(1))\n    for m in re.finditer(r\"\\b\\d{2}-\\d{2}-\\d{2} (\\d{8})\\b\", d.body):\n        keys.add(m.group(1)[-4:])\n    return keys\n\n\ndef x_own_statements(cs, cands):\n    out = []\n    for d in cs.of_type(\"bank_statement\", \"customer_letter\", \"customer_email\", \"cancellation_confirmation\"):\n        holders = statement_holders(d)\n        own = any(h == \"__self__\" or norm(h) == norm(cs.cname) for h in holders)\n        if d.type == \"bank_statement\" and not own:\n            continue\n        if d.type != \"bank_statement\" and not own:\n            continue\n        keys = statement_keys(d)\n        cov = []\n        for t in cands:\n            k = acct_key(t.get(\"counterparty_account\"))\n            if (k and k in keys) or (cs.is_self(t.get(\"counterparty_name\")) and amount_in(t, d)):\n                if amount_in(t, d) or (k and k in keys and d.type == \"bank_statement\"):\n                    cov.append(t[\"transaction_id\"])\n        if cov:\n            onward = sum(cs.t(x)[\"amount_gbp\"] for x in cov if cs.t(x)[\"direction\"] == \"out\")\n            out.append(Expl(\"OWN_ACCOUNT\", \"X2_own_account_statement\", [d.id], cov,\n                            \"%s shows the account %s is held by %s\" % (d.id, sorted(keys)[0] if keys else \"\",\n                                                                       cs.cname), onward))\n    return out\n\n\ndef x_documents(cs, cands):\n    out = []\n    has_factoring = cs.of_type(\"factoring_agreement\")\n    for d in cs.sig_docs:\n        code = EXPLAIN_TYPES.get(d.type)\n        if d.type == \"remittance_advice\" and has_factoring:\n            code = \"THIRD_PARTY_DOCUMENTED\"\n        if not code:\n            continue\n        cov = []\n        if d.type == \"payment_file\":\n            rows = [r for tb in d.tables for r in tb]\n            for r in rows:\n                nm = r.get(\"payee\") or r.get(\"contractor\") or \"\"\n                am = money(r.get(\"amount\", \"\"))\n                for t in cands:\n                    if t[\"direction\"] == \"out\" and norm(t.get(\"counterparty_name\")) == norm(nm) and am and \\\n                            abs(am[0] - t[\"amount_gbp\"]) <= 0.01:\n                        cov.append(t[\"transaction_id\"])\n        else:\n            for t in cands:\n                if amount_in(t, d) and (party_match(t, d) or norm(cs.cname) in d.ntext):\n                    if d.type == \"remittance_advice\" and not any(party_match(t, f) for f in has_factoring):\n                        continue\n                    cov.append(t[\"transaction_id\"])\n        if cov:\n            onward = sum(cs.t(x)[\"amount_gbp\"] for x in cov if cs.t(x)[\"direction\"] == \"out\")\n            sup = [f.id for f in has_factoring] if d.type == \"remittance_advice\" else []\n            out.append(Expl(code, \"X1_document_reconciles\", [d.id] + sup, sorted(set(cov)),\n                            \"%s (%s) reconciles to the amounts\" % (d.id, d.type.replace(\"_\", \" \")), onward))\n    return out\n\n\ndef x_booking(cs, cands):\n    out = []\n    for d in cs.of_type(\"booking_confirmation\"):\n        trav = set(norm(x) for x in re.findall(r\"^\\s*\\d+\\.\\s+(.+?)\\s*$\", d.body, re.M))\n        lead = d.fields.get(\"lead traveller\")\n        if lead:\n            trav.add(norm(lead))\n        m = re.search(r\"transfer to (.+?), account\", d.body)\n        payee = norm(m.group(1)) if m else \"\"\n        cov = []\n        for t in cands:\n            if t[\"direction\"] == \"in\" and norm(t.get(\"counterparty_name\")) in trav:\n                cov.append(t[\"transaction_id\"])\n            elif t[\"direction\"] == \"out\" and payee and norm(t.get(\"counterparty_name\")) == payee and amount_in(t, d):\n                cov.append(t[\"transaction_id\"])\n        if cov:\n            out.append(Expl(\"COLLECTION_DOCUMENTED\", \"X3_group_collection\", [d.id], cov,\n                            \"%s lists %d travellers and the payment to %s\" % (d.id, len(trav), m.group(1) if m else \"\")))\n    return out\n\n\ndef x_group(cs, cands):\n    out = []\n    for d in cs.of_type(\"group_structure\"):\n        edges = []\n        for tb in d.tables:\n            for r in tb:\n                comp = r.get(\"company\")\n                own = r.get(\"owner\") or r.get(\"owned by\")\n                if comp and own:\n                    edges.append((norm(comp), norm(own)))\n        def roots(x, seen=()):\n            ps = [o for c, o in edges if c == x and o not in seen]\n            if not ps:\n                return {x}\n            s = set()\n            for p in ps:\n                s |= roots(p, seen + (x,))\n            return s\n        me = norm(cs.cname)\n        members = set([c for c, _ in edges] + [o for _, o in edges])\n        if me not in members:\n            continue\n        cov = [t[\"transaction_id\"] for t in cands if norm(t.get(\"counterparty_name\")) in members and\n               norm(t.get(\"counterparty_name\")) != me and (roots(norm(t[\"counterparty_name\"])) & roots(me) or\n                                                          norm(t[\"counterparty_name\"]) in roots(me))]\n        if cov:\n            sup = [e.id for e in cs.of_type(\"email\") if re.search(r\"both companies are mine|same group|our group\", e.body, re.I)]\n            out.append(Expl(\"GROUP_COMPANY\", \"X4_group_company\", [d.id] + sup, cov,\n                            \"%s shows %s and the counterparty share an owner\" % (d.id, cs.cname)))\n    return out\n\n\ndef x_redeposit(cs, cands):\n    out = []\n    revs = [r for r in cs.reviews if r[\"rule_id\"] == \"TM05\" and re.search(r\"withdraw\", r[\"note\"], re.I)]\n    for a in cs.alerts_of(\"TM05\"):\n        for tid in a[\"transaction_ids\"]:\n            t = cs.t(tid)\n            if not t or t[\"direction\"] != \"in\":\n                continue\n            for d in chats(cs):\n                if not re.search(r\"\\bback\\b|withdrew|withdrawn|same cash\", customer_lines(d) + d.body, re.I):\n                    continue\n                wd = [w for w in cs.all_txns if w[\"channel\"] == \"cash_withdrawal\" and abs(w[\"amount_gbp\"] - t[\"amount_gbp\"]) < 0.01\n                      and w[\"booked_at\"] < t[\"booked_at\"]]\n                if wd and revs:\n                    cs.edge(wd[-1][\"transaction_id\"], tid, \"explains\")\n                    out.append(Expl(\"DOCUMENTED_EVENT\", \"X5_cash_redeposited\", [d.id, revs[-1][\"review_id\"]],\n                                    [tid, wd[-1][\"transaction_id\"]],\n                                    \"the %s paid in on %s is the cash withdrawn on %s (%s), reviewed and closed in %s \"\n                                    \"(\\\"%s\\\")\" % (fmt(t[\"amount_gbp\"]), dtxt(pdate(t[\"booked_at\"])),\n                                                  dtxt(pdate(wd[-1][\"booked_at\"])), wd[-1][\"transaction_id\"],\n                                                  revs[-1][\"review_id\"], revs[-1][\"note\"])))\n    return out\n\n\ndef x_redemption(cs, cands):\n    out = []\n    for a in cs.alerts_of(\"TM10\"):\n        red = cs.of_type(\"redundancy_letter\")\n        em = [d for d in cs.of_type(\"customer_email\") if re.search(r\"\\bsell|\\bsale|withdraw\", d.body, re.I)]\n        if red and em:\n            out.append(Expl(\"DOCUMENTED_EVENT\", \"X6_redemption_reason_documented\", [red[0].id, em[0].id],\n                            a[\"transaction_ids\"], \"%s confirms redundancy and %s asks to sell the fund to cover living \"\n                                                  \"costs\" % (red[0].id, em[0].id)))\n    return out\n\n\nEXPLAINERS = [x_own_statements, x_documents, x_booking, x_group, x_redeposit, x_redemption]\n\n\n# ----------------------------------------------------------------------------\n# Reconciliation per alert, against the threshold that made the rule fire\n# ----------------------------------------------------------------------------\ndef reconcile(cs, a, covered, onward_credit):\n    r, m = a[\"rule_id\"], a.get(\"measured\") or {}\n    ids = [i for i in a[\"transaction_ids\"] if cs.t(i)]\n    txs = [cs.t(i) for i in ids]\n    prof = [t for t in txs if cs.profile_explained(t)]\n    expl = [t for t in txs if t[\"transaction_id\"] in covered]\n    une = [t for t in txs if t[\"transaction_id\"] not in covered and not cs.profile_explained(t)]\n    rec = {\"alert_id\": a[\"alert_id\"], \"rule\": r, \"alerted_gbp\": round(sum(t[\"amount_gbp\"] for t in txs), 2),\n           \"explained_gbp\": round(sum(t[\"amount_gbp\"] for t in expl), 2),\n           \"profile_gbp\": round(sum(t[\"amount_gbp\"] for t in prof), 2),\n           \"unexplained_gbp\": round(sum(t[\"amount_gbp\"] for t in une), 2),\n           \"unexplained_txns\": [t[\"transaction_id\"] for t in une]}\n    if r == \"TM01\":\n        received = m.get(\"received_gbp\") or sum(t[\"amount_gbp\"] for t in txs if t[\"direction\"] == \"in\")\n        ex_in = sum(t[\"amount_gbp\"] for t in expl if t[\"direction\"] == \"in\")\n        if cs.inst == \"payments_fx\":\n            own_in = sum(t[\"amount_gbp\"] for t in txs if t[\"direction\"] == \"in\" and cs.is_self(t.get(\"counterparty_name\"))\n                         and t[\"transaction_id\"] not in covered)\n            ex_in += min(onward_credit, own_in)\n        lm = cs.pol.get(\"tm01_limit_multiple_\" + (\"business\" if cs.cust.get(\"kind\") == \"business\" else \"individual\"))\n        limit = ((m.get(\"limit_multiple\") or 0) if lm is None else lm) * (m.get(\"baseline_gbp\") or 0)\n        rest = round(received - ex_in, 2)\n        rec[\"unexplained_txns\"] = [t[\"transaction_id\"] for t in txs if t[\"direction\"] == \"in\" and\n                                   t[\"transaction_id\"] not in covered and not (cs.profile_explained(t) and\n                                                                               cs.inst != \"payments_fx\")]\n        rec.update(explained_gbp=round(ex_in, 2), unexplained_gbp=max(rest - limit, 0.0) if rest > limit else 0.0,\n                   residual_activity_gbp=rest, limit_gbp=round(limit, 2))\n        rec[\"cleared\"] = ex_in > 0 and rest <= limit\n    elif r == \"TM02\":\n        un_in = sum(t[\"amount_gbp\"] for t in une if t[\"direction\"] == \"in\")\n        rec[\"cleared\"] = un_in < cs.pol[\"tm02_min\"]\n        rec[\"unexplained_gbp\"] = round(un_in, 2)\n    elif r == \"TM03\":\n        rec[\"cleared\"] = not une\n    elif r == \"TM04\":\n        n = len(set(norm(t[\"counterparty_name\"]) for t in une if t[\"direction\"] == (\n            \"in\" if m.get(\"direction\") == \"incoming\" else \"out\")))\n        rec[\"cleared\"] = n <= (m.get(\"limit\") or 0)\n        rec[\"unexplained_counterparties\"] = n\n    elif r in (\"TM06\", \"TM07\"):\n        rec[\"cleared\"] = sum(t[\"amount_gbp\"] for t in une) < (m.get(\"limit_gbp\") or 5000)\n    elif r in (\"TM05\", \"TM08\", \"TM10\", \"TM22\"):\n        rec[\"cleared\"] = not une\n    else:\n        rec[\"cleared\"] = not une\n    return rec\n\n\n# ----------------------------------------------------------------------------\n# RFI asks\n# ----------------------------------------------------------------------------\ndef describe_txn(t):\n    return \"%s %s %s on %s%s\" % (fmt(t[\"amount_gbp\"]), \"from\" if t[\"direction\"] == \"in\" else \"to\",\n                                 t.get(\"counterparty_name\") or (\"cash at \" + (t.get(\"location\") or \"branch\")),\n                                 dtxt(pdate(t[\"booked_at\"])),\n                                 (\" (ref %s)\" % t[\"reference\"]) if t.get(\"reference\") and t[\"reference\"] not in\n                                 (\"transfer\", \"payment\") else \"\")\n\n\ndef rfi_for(cs, rec):\n    r = rec[\"rule\"]\n    une = [cs.t(i) for i in rec[\"unexplained_txns\"]]\n    une.sort(key=lambda t: (-t[\"amount_gbp\"], t[\"transaction_id\"]))\n    top = une[:3]\n    lst = \"; \".join(describe_txn(t) for t in top)\n    if r == \"TM08\":\n        t = top[0] if top else None\n        cp = (t or {}).get(\"counterparty_name\") or \"\"\n        if re.search(r\"conveyanc|solicitor|client account\", cp, re.I):\n            return (\"RFI_SOURCE_OF_FUNDS\", \"Ask the customer for the completion statement or solicitor's letter showing \"\n                    \"what the %s is (e.g. a property sale) and that it belongs to them.\" % lst)\n        if \"&\" in cp:\n            return (\"RFI_COUNTERPARTY_DETAILS\", \"Ask the customer for a statement or bank letter showing that they are a \"\n                    \"holder of the joint account '%s' that sent %s; a similar name alone does not show it is their own \"\n                    \"account.\" % (cp, lst))\n        if re.search(r\"finance|factor\", cp, re.I):\n            return (\"RFI_COUNTERPARTY_DETAILS\", \"Ask the client for the invoice-finance or factoring agreement with %s and \"\n                    \"the remittance advice for %s.\" % (cp, lst))\n        return (\"RFI_COUNTERPARTY_DETAILS\", \"Ask the customer who %s is, their relationship to the customer and what %s \"\n                \"was for.\" % (cp or \"the third party\", lst))\n    if r == \"TM04\" and cs.inst == \"payments_fx\":\n        n = len(set(norm(t[\"counterparty_name\"]) for t in une))\n        return (\"RFI_BUSINESS_RECORDS\", \"Ask the client for the business records (invoices, contracts or a payment \"\n                \"file) behind the payments to %d beneficiaries in the window, starting with %s.\" % (n, lst))\n    if r in (\"TM02\", \"TM04\", \"TM10\"):\n        if cs.inst == \"payments_fx\":\n            return (\"RFI_BUSINESS_RECORDS\", \"Ask the client for the business records behind the activity: invoices or \"\n                    \"shipment records for the payments received from third parties and paid on (%s).\" % lst)\n        if r == \"TM10\":\n            return (\"RFI_PURPOSE_DOCUMENTS\", \"Ask the customer why the fund units were sold back so soon (%s) and for a \"\n                    \"document supporting the reason.\" % lst)\n        return (\"RFI_PURPOSE_DOCUMENTS\", \"Ask the customer for documents showing what these payments were for (%s), \"\n                \"e.g. the agreement, booking or invoice behind them.\" % lst)\n    if r == \"TM03\":\n        return (\"RFI_PURPOSE_DOCUMENTS\", \"Ask the client for the invoice or contract covering the split payments (%s); \"\n                \"payments of this size need an invoice on file.\" % lst)\n    if r == \"TM06\":\n        return (\"RFI_PURPOSE_DOCUMENTS\", \"Ask for documents showing the purpose of the payments to or from %s (%s).\" % (\n            (rec.get(\"country\") or \"the higher-risk country\"), lst))\n    if r in (\"TM03\", \"TM07\") and cs.inst == \"payments_fx\":\n        return (\"RFI_PURPOSE_DOCUMENTS\", \"Ask the client for the invoice or contract behind the payments (%s), showing \"\n                \"what was bought and from whom.\" % lst)\n    if r == \"TM01\" and cs.inst == \"payments_fx\":\n        return (\"RFI_BUSINESS_RECORDS\", \"Ask the client for the business records behind the %s received in the window \"\n                \"(%s in excess of its declared volume), e.g. the orders, invoices or contracts the funds relate to.\" % (\n                    fmt(rec.get(\"residual_activity_gbp\") or rec[\"alerted_gbp\"]), fmt(rec.get(\"unexplained_gbp\") or 0)))\n    # TM01, TM05, TM07 and others: where did the money come from\n    return (\"RFI_SOURCE_OF_FUNDS\", \"Ask the customer for proof of where the money came from for %s, e.g. a letter, \"\n            \"contract or statement from the payer.\" % (lst or \"the activity\"))\n\n\nRFI_PRIORITY = [\"TM22\", \"TM08\", \"TM10\", \"TM04\", \"TM02\", \"TM03\", \"TM06\", \"TM05\", \"TM07\", \"TM01\"]\n\n\n# ----------------------------------------------------------------------------\n# Close reasons\n# ----------------------------------------------------------------------------\nCLOSE_LEAD = {\n    \"LIST_MATCH_DIFFERENT_PARTY\": \"The internal-list match is a different party.\",\n    \"RETURNING_CUSTOMER\": \"The returning customer has been re-verified and the reactivation activity is explained.\",\n    \"COLLECTION_DOCUMENTED\": \"The payments are a documented group collection.\",\n    \"BUSINESS_RECORDS_RECONCILE\": \"The business's own records reconcile to the alerted activity.\",\n    \"GROUP_COMPANY\": \"The counterparty is a company in the customer's own group.\",\n    \"REFUND_OF_EARLIER_PAYMENT\": \"The funds are a refund of an earlier payment.\",\n    \"DOCUMENTED_EVENT\": \"The activity is explained by a documented one-off event.\",\n    \"INVOICE_MATCHES\": \"The payments match invoices on file.\",\n    \"THIRD_PARTY_DOCUMENTED\": \"The third-party funds are documented.\",\n    \"OWN_ACCOUNT\": \"The money moved between accounts the customer is shown to hold.\",\n    \"WITHIN_PROFILE\": \"The alerted activity is within the customer's declared profile.\",\n}\n\n\ndef expl_sentence(cs, e):\n    ts = [cs.t(x) for x in e.txns if cs.t(x)]\n    ts.sort(key=lambda t: (-t[\"amount_gbp\"], t[\"transaction_id\"]))\n    parts = [\"%s %s\" % (t[\"transaction_id\"], describe_txn(t)) for t in ts[:2]]\n    more = (\" and %d more\" % (len(ts) - 2)) if len(ts) > 2 else \"\"\n    return \"%s, covering %s%s.\" % (e.note[0].upper() + e.note[1:], \"; \".join(parts), more)\n\n\ndef case_alert_summary(cs):\n    bits = []\n    for a in cs.alerts:\n        m = a.get(\"measured\") or {}\n        bits.append(\"%s (%s)\" % (a[\"alert_id\"], a[\"rule_id\"]))\n    return \", \".join(bits)\n\n\n# ----------------------------------------------------------------------------\n# Decision ladder\n# ----------------------------------------------------------------------------\ndef decide(cs):\n    \"\"\"Returns (code, reason, evidence, trace_extra).\"\"\"\n    trace = {\"reconciliation\": [], \"tm22\": []}\n    # 1. suspicion facts -> ESCALATE\n    for rule in SUSPICION_RULES:\n        f = rule(cs)\n        if f:\n            cs.fire(f.rule, f.code, f.facts)\n            return f.code, f.reason, f.evidence, trace\n    # 2. internal list\n    tm22 = []\n    for a in cs.alerts_of(\"TM22\"):\n        res = resolve_tm22(cs, a)\n        tm22.append(res)\n        trace[\"tm22\"].append({k: (v if not isinstance(v, (date, dict)) else str(v) if isinstance(v, date) else None)\n                              for k, v in res.items() if k != \"txn\"})\n        cs.fire(\"R_TM22_%s\" % res[\"basis\"].replace(\" \", \"_\"), res[\"status\"], [res.get(\"fact\")] if res.get(\"fact\") else [])\n        if res[\"status\"] == \"confirmed\":\n            t = res.get(\"txn\")\n            reason = (\"Alert %s matched %s to list entry %s (%s) on %s. %s. Under policy a listed party that is the \"\n                      \"counterparty or controls it at the time of payment must be escalated, even where the role \"\n                      \"later ended.\" % (a[\"alert_id\"], (t or {}).get(\"counterparty_name\", \"the counterparty\"),\n                                        res[\"entry\"], res[\"lname\"], res[\"basis\"], res[\"note\"][0].upper() + res[\"note\"][1:]))\n            ev = [a[\"alert_id\"], res[\"entry\"]] + res[\"docs\"] + list(a[\"transaction_ids\"])\n            return \"ESC_LISTED_PARTY\", reason, ev, trace\n    # 3. explanations and reconciliation\n    cands = cs.window_txns()\n    expls = []\n    for x in EXPLAINERS:\n        for e in x(cs, cands):\n            expls.append(e)\n            fid = cs.fact(\"explains\", e.docs + e.txns, code=e.code, rule=e.rule)\n            cs.fire(e.rule, e.code, [fid], docs=e.docs, txns=e.txns)\n            for d in e.docs:\n                for t in e.txns:\n                    cs.edge(d, t, \"explains\")\n    covered = {}\n    for e in expls:\n        for t in e.txns:\n            covered.setdefault(t, []).append(e)\n    onward = sum(e.onward for e in expls if e.code in (\"OWN_ACCOUNT\", \"INVOICE_MATCHES\"))\n    recs = []\n    for a in cs.alerts:\n        if a[\"rule_id\"] == \"TM22\":\n            res = [r for r in tm22 if r.get(\"entry\") == (a.get(\"measured\") or {}).get(\"list_entry\")]\n            st = res[0][\"status\"] if res else \"unsettled\"\n            rec = reconcile(cs, a, covered, onward)\n            rec[\"cleared\"] = st == \"cleared\"\n            rec[\"list_status\"] = st\n        else:\n            rec = reconcile(cs, a, covered, onward)\n        rec[\"explained_by\"] = sorted(set(d for t in a[\"transaction_ids\"] for e in covered.get(t, []) for d in e.docs))\n        recs.append(rec)\n        cs.fire(\"R_RECONCILE_%s\" % a[\"rule_id\"], \"cleared\" if rec[\"cleared\"] else \"open\", [],\n                alert=a[\"alert_id\"])\n    trace[\"reconciliation\"] = recs\n    open_recs = [r for r in recs if not r[\"cleared\"]]\n    all_text = \" \".join(d.body for d in cs.sig_docs) + \" \" + \" \".join(r[\"note\"] for r in cs.reviews)\n    # 3a. unsettled: keyword suspicion escalates, else RFI\n    if open_recs:\n        if SUSPICION_WORDS.search(all_text):\n            w = SUSPICION_WORDS.search(all_text).group(0)\n            src = [d.id for d in cs.sig_docs if SUSPICION_WORDS.search(d.body)]\n            cs.fire(\"R_KEYWORD_SUSPICION\", \"ESC_UNEXPLAINED_FUNDS\", [cs.fact(\"suspicion_keyword\", src, word=w)])\n            return (\"ESC_UNEXPLAINED_FUNDS\", \"The activity on %s is not reconciled to evidence and %s refers to '%s'. \"\n                    \"Unexplained activity with that indicator is escalated.\" % (case_alert_summary(cs),\n                                                                               \", \".join(src[:2]), w),\n                    [r[\"alert_id\"] for r in open_recs] + src[:3], trace)\n        prio = RFI_PRIORITY\n        if cs.inst == \"payments_fx\":  # a business's third-party flows: business records come first\n            prio = [\"TM22\", \"TM02\", \"TM04\", \"TM08\"] + [x for x in RFI_PRIORITY if x not in (\"TM22\", \"TM02\", \"TM04\", \"TM08\")]\n        open_recs.sort(key=lambda r: (prio.index(r[\"rule\"]) if r[\"rule\"] in prio else 99, r[\"alert_id\"]))\n        r0 = open_recs[0]\n        a0 = [a for a in cs.alerts if a[\"alert_id\"] == r0[\"alert_id\"]][0]\n        # cash deposits split under a threshold with nothing on file -> structuring\n        if r0[\"rule\"] == \"TM03\" and all((cs.t(t) or {}).get(\"channel\", \"\").startswith(\"cash\") for t in a0[\"transaction_ids\"]) \\\n                and not cs.sig_docs:\n            m = a0.get(\"measured\") or {}\n            reason = (\"Alert %s: %d cash deposits totalling %s, each below the reporting threshold, with no business \"\n                      \"records or other explanation on file. The pattern is consistent with structuring.\" % (\n                          a0[\"alert_id\"], len(a0[\"transaction_ids\"]), fmt(r0[\"alerted_gbp\"])))\n            return \"ESC_STRUCTURING\", reason, [a0[\"alert_id\"]] + a0[\"transaction_ids\"], trace\n        if r0[\"rule\"] == \"TM22\":\n            res = [r for r in tm22 if r.get(\"entry\") == (a0.get(\"measured\") or {}).get(\"list_entry\")][0]\n            t = res.get(\"txn\") or {}\n            code = \"RFI_COUNTERPARTY_DETAILS\"\n            ask = (\"Ask the customer for details identifying %s (date of birth, address or company registration) so \"\n                   \"it can be confirmed whether they are %s on list entry %s; %s.\" % (\n                       t.get(\"counterparty_name\", \"the counterparty\"), res.get(\"lname\"), res.get(\"entry\"), res.get(\"note\")))\n            ev = [a0[\"alert_id\"], res.get(\"entry\")] + a0[\"transaction_ids\"] + res[\"docs\"]\n        else:\n            code, ask = rfi_for(cs, r0)\n            if cs.inst == \"payments_fx\" and r0[\"rule\"] in (\"TM01\", \"TM03\", \"TM07\") and code != \"RFI_BUSINESS_RECORDS\":\n                code = \"RFI_PURPOSE_DOCUMENTS\"\n            ev = [a0[\"alert_id\"]] + r0[\"unexplained_txns\"][:10] + r0[\"explained_by\"]\n        if r0[\"rule\"] == \"TM22\":\n            reason = (\"Alert %s matched %s to internal-list entry %s (%s) on %s, and nothing on file settles whether \"\n                      \"they are the same party. %s\" % (a0[\"alert_id\"], t.get(\"counterparty_name\", \"the counterparty\"),\n                                                       res.get(\"entry\"), res.get(\"lname\"), res.get(\"basis\"),\n                                                       ask.split(\"; \")[0] + \".\"))\n        else:\n            reason = (\"Alert %s (%s) is not fully explained: %s of the alerted %s is not reconciled to any document \"\n                      \"on file. %s\" % (a0[\"alert_id\"], a0[\"rule_id\"], fmt(r0[\"unexplained_gbp\"]) if\n                                       r0[\"unexplained_gbp\"] else \"part\", fmt(r0[\"alerted_gbp\"]), ask))\n        cs.fire(\"R_RFI\", code, [], alert=a0[\"alert_id\"])\n        return code, reason, ev, trace\n    # 3b. payments_fx: held payment >= threshold to a non-client needs an invoice\n    if cs.pol[\"invoice_required_gbp\"] and cs.held and cs.t(cs.held):\n        h = cs.t(cs.held)\n        if h[\"amount_gbp\"] >= cs.pol[\"invoice_required_gbp\"] and not cs.is_self(h.get(\"counterparty_name\")) and \\\n                not any(d.type in INVOICE_LIKE for d in cs.sig_docs) and not covered.get(cs.held):\n            return (\"RFI_PURPOSE_DOCUMENTS\", \"Held payment %s of %s is not covered by any invoice on file. Payments of \"\n                    \"%s or more to a non-client need an invoice; ask the client for the invoice or contract behind \"\n                    \"it.\" % (cs.held, describe_txn(h), fmt(cs.pol[\"invoice_required_gbp\"])), [cs.held], trace)\n    # 4. own-account at >= 5x profile -> profile update\n    for a in cs.alerts_of(\"TM01\"):\n        m = a.get(\"measured\") or {}\n        es = [e for t in a[\"transaction_ids\"] for e in covered.get(t, [])]\n        if cs.inst == \"payments_fx\" and not [e for e in es if e.direction_in(cs)]:\n            es = es + [e for e in expls if e.onward > 0]\n        if es and all(e.code == \"OWN_ACCOUNT\" for e in es) and (m.get(\"multiple\") or 0) >= cs.pol[\"own_account_rfi_multiple\"]:\n            docs = sorted(set(d for e in es for d in e.docs))\n            reason = (\"Alert %s: %s received in the window, %.1fx the declared monthly %s. %s shows the money came from \"\n                      \"the customer's own account, but activity at %.0fx or more of the declared profile needs an \"\n                      \"updated profile; ask the customer to confirm their expected monthly activity and the reason for \"\n                      \"the change.\" % (a[\"alert_id\"], fmt(m.get(\"received_gbp\") or 0), m.get(\"multiple\") or 0,\n                                       fmt(m.get(\"baseline_gbp\") or 0), \", \".join(docs), cs.pol[\"own_account_rfi_multiple\"]))\n            cs.fire(\"R_OWN_ACCOUNT_PROFILE_UPDATE\", \"RFI_UPDATED_PROFILE\", [])\n            return \"RFI_UPDATED_PROFILE\", reason, [a[\"alert_id\"]] + docs, trace\n    # 5. CLOSE: every alert reconciled\n    codes = set(e.code for e in expls)\n    if any(r.get(\"list_status\") == \"cleared\" for r in recs):\n        codes.add(\"LIST_MATCH_DIFFERENT_PARTY\")\n    if cs.alerts_of(\"TM07\") and cs.of_type(\"reverification_record\"):\n        codes.add(\"RETURNING_CUSTOMER\")\n    if not codes:\n        codes.add(\"WITHIN_PROFILE\")\n    code = [c for c in CLOSE_PRIORITY if c in codes][0]\n    sents = [CLOSE_LEAD[code]]\n    ev = []\n    if code == \"LIST_MATCH_DIFFERENT_PARTY\":\n        for res in tm22:\n            if res[\"status\"] == \"cleared\":\n                sents.append(res[\"note\"][0].upper() + res[\"note\"][1:] + \".\")\n                ev += [res[\"entry\"]] + res[\"docs\"]\n    if code == \"RETURNING_CUSTOMER\":\n        rv = cs.of_type(\"reverification_record\")[0]\n        sents.append(\"%s records the re-verification of %s.\" % (rv.id, cs.cname))\n        ev.append(rv.id)\n    used = [e for e in expls if e.code == code] + [e for e in expls if e.code != code]\n    groups = []\n    for e in used:\n        g = [x for x in groups if set(x[0].txns) == set(e.txns) and x[0].code == e.code]\n        if g:\n            g[0].append(e)\n        else:\n            groups.append([e])\n    for g in groups[:2]:\n        e = g[0]\n        if len(g) > 1:\n            e = Expl(e.code, e.rule, [d for x in g for d in x.docs], e.txns,\n                     \" and \".join(x.note for x in g))\n        sents.append(expl_sentence(cs, e))\n        ev += e.docs + e.txns[:6]\n    prof = sorted(set(cs.profile_explained(cs.t(t)) for t in cs.alerted if cs.t(t) and cs.profile_explained(cs.t(t))))\n    if prof and len(sents) < 4:\n        sents.append(\"Remaining alerted items are %s.\" % \", \".join(prof))\n    if len(sents) < 2:\n        sents.append(\"Alerts %s reconcile with nothing left unexplained.\" % case_alert_summary(cs))\n    ev += [r[\"alert_id\"] for r in recs]\n    cs.fire(\"R_CLOSE\", code, [])\n    return code, \" \".join(sents[:4]), ev, trace\n\n\n\n# ----------------------------------------------------------------------------\n# Reason length guard: 2-4 sentences, counted robustly\n# ----------------------------------------------------------------------------\n_ABBR = re.compile(r\"\\b(?:Sp\\. z o\\.o\\.|e\\.g\\.|i\\.e\\.|etc\\.|No\\.|NO\\.|INV\\.|Co\\.|Ltd\\.|Inc\\.|St\\.|Mr\\.|Mrs\\.|Ms\\.|Dr\\.|vs\\.|\"\n                   r\"approx\\.|S\\.A\\.|S\\.L\\.|B\\.V\\.|N\\.V\\.|A\\.S\\.|L\\.L\\.C\\.)\", re.I)\n\n\ndef split_sentences(text):\n    \"\"\"Split into sentences, ignoring dots inside quotes, parentheses, abbreviations and numbers.\"\"\"\n    mask = list(text)\n    def blank(a, b):\n        for i in range(a, b):\n            if mask[i] in \".!?\":\n                mask[i] = \"_\"\n    for m in re.finditer(r'\"[^\"]*\"|\\([^()]*\\)|\\d\\.\\d', text):\n        blank(m.start(), m.end())\n    for m in _ABBR.finditer(text):\n        blank(m.start(), m.end())\n    masked = \"\".join(mask)\n    out, start = [], 0\n    for m in re.finditer(r\"[.!?](?=\\s+[A-Z0-9£\\\"(]|\\s*$)\", masked):\n        out.append(text[start:m.end()].strip())\n        start = m.end()\n    if text[start:].strip():\n        out.append(text[start:].strip())\n    return [x for x in out if x]\n\n\ndef clamp_reason(reason, cs):\n    ss = split_sentences(reason)\n    if len(ss) > 4:\n        head, tail = ss[:3], ss[3:]\n        merged = \"; \".join(x.rstrip(\".\") for x in tail) + \".\"\n        ss = head + [merged]\n    if len(ss) < 2:\n        ss.append(\"Alerts reviewed: %s.\" % case_alert_summary(cs))\n    return \" \".join(ss)\n\n\ndef advisory_reconcile(cs, trace):\n    \"\"\"For cases decided before reconciliation (suspicion or a confirmed list match), still book the alerted\n    pounds against the evidence, for the trace only. It never changes the verdict; firings are marked advisory.\"\"\"\n    cands = cs.window_txns()\n    expls = []\n    for x in EXPLAINERS:\n        for e in x(cs, cands):\n            expls.append(e)\n            fid = cs.fact(\"explains\", e.docs + e.txns, code=e.code, rule=e.rule)\n            cs.fire(e.rule, e.code, [fid], docs=e.docs, txns=e.txns, advisory=True)\n            for d in e.docs:\n                for t in e.txns:\n                    cs.edge(d, t, \"explains\")\n    covered = {}\n    for e in expls:\n        for t in e.txns:\n            covered.setdefault(t, []).append(e)\n    onward = sum(e.onward for e in expls if e.code in (\"OWN_ACCOUNT\", \"INVOICE_MATCHES\"))\n    recs = []\n    for a in cs.alerts:\n        rec = reconcile(cs, a, covered, onward)\n        rec[\"explained_by\"] = sorted(set(d for t in a[\"transaction_ids\"] for e in covered.get(t, []) for d in e.docs))\n        rec[\"advisory\"] = True\n        recs.append(rec)\n        cs.fire(\"R_RECONCILE_%s\" % a[\"rule_id\"], \"cleared\" if rec[\"cleared\"] else \"open\", [], alert=a[\"alert_id\"],\n                advisory=True)\n    trace[\"reconciliation\"] = recs\n\n\ndef decision_index(cs):\n    idx = [i for i, f in enumerate(cs.firings) if not f.get(\"advisory\")]\n    return idx[-1] if idx else len(cs.firings) - 1\n\n\ndef fallback(cs, err):\n    text = \"\"\n    try:\n        text = \" \".join(d.body for d in cs.sig_docs)\n    except Exception:\n        pass\n    if SUSPICION_WORDS.search(text):\n        return \"ESC_UNEXPLAINED_FUNDS\", \"Automated review could not complete; documents contain suspicion indicators.\"\n    return \"RFI_SOURCE_OF_FUNDS\", (\"Automated review could not reconcile the alerted activity; ask the customer for \"\n                                   \"evidence of the source and purpose of the alerted funds.\")\n\n\n# ----------------------------------------------------------------------------\n# Output\n# ----------------------------------------------------------------------------\ndef finalize_evidence(cs, ev, code):\n    ev = [e for e in ev if e in cs.valid_ids]\n    if cs.held and cs.held in cs.valid_ids:\n        ev.append(cs.held)\n    ev = [e for e in ev if e != cs.c[\"customer_id\"] and e != cs.id]\n    return sorted(set(ev))\n\n\ndef build_trace(cs, code, verdict, ev, extra):\n    nodes = [{\"id\": cs.c[\"customer_id\"], \"type\": \"customer\", \"label\": cs.cname}]\n    for a in cs.alerts:\n        nodes.append({\"id\": a[\"alert_id\"], \"type\": \"alert\", \"label\": a[\"rule_id\"]})\n        cs.edge(a[\"alert_id\"], cs.c[\"customer_id\"], \"fired_on\")\n        for t in a.get(\"transaction_ids\", []):\n            cs.edge(a[\"alert_id\"], t, \"fired_on\")\n    seen = set()\n    for t in cs.alerted + ([cs.held] if cs.held else []):\n        if t in cs.tx and t not in seen:\n            seen.add(t)\n            x = cs.tx[t]\n            nodes.append({\"id\": t, \"type\": \"transaction\", \"label\": describe_txn(x)})\n    for d in cs.docs:\n        nodes.append({\"id\": d.id, \"type\": \"document\", \"label\": d.type})\n    for le, L in sorted(cs.list_entries.items()):\n        nodes.append({\"id\": le, \"type\": \"list_entry\", \"label\": L.get(\"name\")})\n    for i, f in enumerate(cs.firings):\n        nodes.append({\"id\": \"R%d\" % (i + 1), \"type\": \"rule\", \"label\": f[\"rule\"], \"outcome\": f[\"outcome\"]})\n        if f.get(\"alert\"):\n            cs.edge(f[\"alert\"], \"R%d\" % (i + 1), \"fired_on\")\n        for d in f.get(\"docs\", []):\n            cs.edge(d, \"R%d\" % (i + 1), \"supports\")\n        for fid in f[\"facts\"]:\n            if fid:\n                for fact in cs.facts:\n                    if fact[\"id\"] == fid:\n                        for s in fact[\"sources\"]:\n                            cs.edge(s, \"R%d\" % (i + 1), \"supports\")\n    nodes.append({\"id\": \"VERDICT\", \"type\": \"verdict\", \"label\": \"%s / %s\" % (verdict, code)})\n    for e in ev:\n        cs.edge(e, \"VERDICT\", \"supports\")\n    di = decision_index(cs)\n    for i, f in enumerate(cs.firings):\n        if (f[\"rule\"].startswith(\"R_RECONCILE\") and not f.get(\"advisory\")) or i == di:\n            cs.edge(\"R%d\" % (i + 1), \"VERDICT\", \"supports\" if f[\"outcome\"] != \"open\" or verdict != \"CLOSE\" else \"contradicts\")\n    known = set(n[\"id\"] for n in nodes)\n    edges = [{\"from\": s, \"to\": d, \"rel\": r} for s, d, r in cs.edges]\n    for e in edges:\n        for k in (\"from\", \"to\"):\n            if e[k] not in known:\n                known.add(e[k])\n                nodes.append({\"id\": e[k], \"type\": \"transaction\" if e[k] in cs.tx else \"record\", \"label\": e[k]})\n    for n in nodes:\n        n[\"class\"] = node_class(n, cs)\n    for e in edges:\n        e[\"property\"] = EDGE_PROP.get(e[\"rel\"], e[\"rel\"])\n    return {\"case_id\": cs.id, \"verdict\": verdict, \"reason_code\": code, \"nodes\": nodes, \"edges\": edges,\n            \"facts\": cs.facts, \"firings\": cs.firings, \"reconciliation\": extra.get(\"reconciliation\", []),\n            \"list_resolution\": extra.get(\"tm22\", [])}\n\n\n\n# ----------------------------------------------------------------------------\n# Ontology vocabulary (system/ontology/proof.owl) used by the trace and the RDF export\n# ----------------------------------------------------------------------------\nONTO_NS = \"https://proof.example/ontology#\"\nNODE_CLASS = {\"customer\": \"Customer\", \"alert\": \"Alert\", \"transaction\": \"Transaction\", \"document\": \"Document\",\n              \"list_entry\": \"ListEntry\", \"rule\": \"ReasoningRule\", \"verdict\": \"Verdict\", \"record\": \"Document\"}\nEDGE_PROP = {\"fired_on\": \"firedOn\", \"supports\": \"supports\", \"contradicts\": \"contradicts\",\n             \"matches\": \"matchesListEntry\", \"explains\": \"explains\", \"holds\": \"hasEvidence\"}\nDOC_CLASS = {\n    \"invoice\": \"Invoice\", \"supplier_invoice\": \"Invoice\", \"supplier_invoices\": \"Invoice\", \"dealer_invoice\": \"Invoice\",\n    \"hospital_invoice\": \"Invoice\", \"carrier_invoice\": \"Invoice\", \"receipt\": \"Invoice\", \"credit_note\": \"Invoice\",\n    \"purchase_order\": \"Invoice\", \"contract_schedule\": \"Invoice\", \"supply_contract\": \"Invoice\",\n    \"consulting_contract\": \"Invoice\", \"sale_receipt\": \"Invoice\", \"vehicle_sale_receipt\": \"EventDoc\",\n    \"bank_statement\": \"AccountProof\",\n    \"solicitor_letter\": \"EventDoc\", \"insurer_letter\": \"EventDoc\", \"settlement_letter\": \"EventDoc\",\n    \"completion_statement\": \"EventDoc\", \"deposit_return_letter\": \"EventDoc\", \"holding_deposit_receipt\": \"EventDoc\",\n    \"loan_agreement\": \"EventDoc\", \"redundancy_letter\": \"EventDoc\", \"cancellation_confirmation\": \"EventDoc\",\n    \"venue_email\": \"EventDoc\", \"insurance_schedule\": \"EventDoc\", \"employment_contract\": \"EventDoc\", \"advert\": \"EventDoc\",\n    \"gift_letter\": \"ThirdPartyDoc\", \"factoring_agreement\": \"ThirdPartyDoc\", \"remittance_advice\": \"ThirdPartyDoc\",\n    \"booking_confirmation\": \"BusinessRecord\", \"cash_collection_reports\": \"BusinessRecord\",\n    \"cash_handling_procedure\": \"BusinessRecord\", \"cash_reconciliation\": \"BusinessRecord\", \"takings_book\": \"BusinessRecord\",\n    \"freight_invoices\": \"BusinessRecord\", \"payment_file\": \"BusinessRecord\", \"management_accounts\": \"BusinessRecord\",\n    \"ticket_report\": \"BusinessRecord\",\n    \"company_register_extract\": \"CompanyRegister\", \"significant_control_register\": \"ControlRegister\",\n    \"group_structure\": \"GroupStructure\",\n    \"sending_bank_fraud_report\": \"ScamReport\",\n    \"support_chat\": \"Correspondence\", \"customer_email\": \"Correspondence\", \"customer_letter\": \"Correspondence\",\n    \"email\": \"Correspondence\", \"staff_note\": \"StaffNote\", \"contact_note\": \"Correspondence\",\n    \"due_diligence_summary\": \"IdentityRecord\", \"proof_of_address\": \"IdentityRecord\",\n    \"reverification_record\": \"IdentityRecord\", \"device_export\": \"DeviceRecord\",\n}\n\n\ndef rule_class(name):\n    if re.match(r\"S\\d+_\", name):\n        return \"SuspicionRule\"\n    if name.startswith(\"R_TM22\"):\n        return \"ListResolutionRule\"\n    if re.match(r\"X\\d+_\", name):\n        return \"ExplanationRule\"\n    if name.startswith(\"R_RECONCILE\"):\n        return \"ReconciliationRule\"\n    return \"DecisionRule\"\n\n\ndef node_class(n, cs):\n    if n[\"type\"] == \"document\":\n        return DOC_CLASS.get(n.get(\"label\"), \"Document\")\n    if n[\"type\"] == \"record\":\n        if any(r[\"review_id\"] == n[\"id\"] for r in cs.reviews):\n            return \"PriorReview\"\n        if n[\"id\"] in cs.tx:\n            return \"Transaction\"\n        return \"Document\"\n    if n[\"type\"] == \"rule\":\n        return rule_class(n.get(\"label\", \"\"))\n    return NODE_CLASS.get(n[\"type\"], \"Document\")\n\n\ndef _lit(v):\n    if isinstance(v, bool):\n        return '\"%s\"^^xsd:boolean' % (\"true\" if v else \"false\")\n    if isinstance(v, (int, float)):\n        return '\"%.2f\"^^xsd:decimal' % v\n    s = str(v)\n    if re.fullmatch(r\"\\d{4}-\\d{2}-\\d{2}\", s):\n        return '\"%s\"^^xsd:date' % s\n    return json.dumps(s, ensure_ascii=False)\n\n\ndef _iri(x):\n    return \"pd:\" + re.sub(r\"[^A-Za-z0-9_\\-]\", \"_\", str(x))\n\n\ndef kg_triples(cs, tr, out):\n    \"\"\"Asserted facts + engine conclusions for one case, as Turtle triple lines (sorted by caller).\"\"\"\n    T = set()\n    cid = cs.id\n    loc = lambda x: _iri(cid + \"_\" + x) if x in (\"VERDICT\",) or re.fullmatch(r\"[RF]\\d+\", x) else _iri(x)\n    add = lambda s_, p_, o_: T.add(\"%s %s %s .\" % (s_, p_, o_))\n    case = _iri(cid)\n    add(case, \"a\", \"proof:Case\")\n    add(case, \"proof:sourceId\", _lit(cid))\n    add(case, \"proof:concerns\", _iri(cs.c[\"customer_id\"]))\n    add(case, \"proof:hasVerdict\", loc(\"VERDICT\"))\n    if cs.held:\n        add(case, \"proof:heldPayment\", _iri(cs.held))\n    for n in tr[\"nodes\"]:\n        s_ = loc(n[\"id\"])\n        add(s_, \"a\", \"proof:\" + node_class(n, cs))\n        add(s_, \"proof:sourceId\", _lit(n[\"id\"]))\n        if n[\"type\"] == \"customer\":\n            add(s_, \"proof:name\", _lit(cs.cname))\n            add(s_, \"proof:partyKind\", _lit(cs.cust.get(\"kind\") or \"\"))\n            for acc in sorted(set(t.get(\"account_id\") for t in cs.all_txns if t.get(\"account_id\"))):\n                add(s_, \"proof:holdsAccount\", _iri(acc))\n                add(_iri(acc), \"a\", \"proof:Account\")\n        elif n[\"type\"] == \"alert\":\n            add(case, \"proof:hasAlert\", s_)\n            a = [x for x in cs.alerts if x[\"alert_id\"] == n[\"id\"]]\n            if a:\n                add(s_, \"proof:ruleId\", _lit(a[0][\"rule_id\"]))\n                add(s_, \"proof:triggeredBy\", \"proof:\" + re.sub(r\"\\W\", \"_\", a[0][\"rule_id\"]))\n        elif n[\"id\"] in cs.tx:\n            t = cs.tx[n[\"id\"]]\n            add(s_, \"proof:amount\", _lit(float(t[\"amount_gbp\"])))\n            add(s_, \"proof:date\", _lit((t.get(\"booked_at\") or \"\")[:10]))\n            add(s_, \"proof:direction\", _lit(t[\"direction\"]))\n            add(s_, \"proof:channel\", _lit(t.get(\"channel\") or \"\"))\n            if t.get(\"reference\"):\n                add(s_, \"proof:reference\", _lit(t[\"reference\"]))\n            if t.get(\"account_id\"):\n                add(s_, \"proof:onAccount\", _iri(t[\"account_id\"]))\n            if t.get(\"counterparty_name\"):\n                cp = _iri(\"CP_\" + norm(t[\"counterparty_name\"]).replace(\" \", \"_\"))\n                add(s_, \"proof:hasCounterparty\", cp)\n                add(cp, \"a\", \"proof:Customer\" if cs.is_self(t[\"counterparty_name\"]) else \"proof:Counterparty\")\n                add(cp, \"proof:name\", _lit(t[\"counterparty_name\"]))\n                if t.get(\"counterparty_country\"):\n                    add(cp, \"proof:country\", _lit(t[\"counterparty_country\"]))\n        elif n[\"type\"] == \"document\":\n            add(s_, \"proof:docType\", _lit(n.get(\"label\") or \"\"))\n            add(_iri(cs.c[\"customer_id\"]), \"proof:hasEvidence\", s_)\n            d = [x for x in cs.docs if x.id == n[\"id\"]]\n            if d and d[0].dated:\n                add(s_, \"proof:date\", _lit(d[0].dated.isoformat()))\n        elif n[\"type\"] == \"list_entry\":\n            add(s_, \"proof:name\", _lit(n.get(\"label\") or \"\"))\n        elif n[\"type\"] == \"rule\":\n            add(s_, \"proof:ruleName\", _lit(n.get(\"label\") or \"\"))\n            add(s_, \"proof:outcome\", _lit(n.get(\"outcome\") or \"\"))\n    for i, f in enumerate(tr[\"firings\"]):\n        for fid in f.get(\"facts\") or []:\n            if fid:\n                add(loc(\"R%d\" % (i + 1)), \"proof:usesFact\", loc(fid))\n    for f in tr[\"facts\"]:\n        s_ = loc(f[\"id\"])\n        add(s_, \"a\", \"proof:Fact\")\n        add(s_, \"proof:factKind\", _lit(f[\"kind\"]))\n        for src in f[\"sources\"]:\n            add(s_, \"proof:hasSource\", _iri(src))\n        for k in sorted(f):\n            if k not in (\"id\", \"kind\", \"sources\") and f[k] is not None:\n                add(s_, \"proof:factValue\", _lit(\"%s=%s\" % (k, f[k])))\n    for e in tr[\"edges\"]:\n        add(loc(e[\"from\"]), \"proof:\" + EDGE_PROP.get(e[\"rel\"], e[\"rel\"]), loc(e[\"to\"]))\n    v = loc(\"VERDICT\")\n    add(v, \"proof:verdictValue\", _lit(out[\"verdict\"]))\n    add(v, \"proof:verdictOf\", \"proof:\" + out[\"verdict\"])\n    add(v, \"proof:hasReasonCode\", \"proof:\" + out[\"reason_code\"])\n    add(v, \"proof:reasonText\", _lit(out[\"reason\"]))\n    if tr[\"firings\"]:\n        add(v, \"proof:decidedBy\", loc(\"R%d\" % (decision_index(cs) + 1)))\n    for eid in out[\"evidence\"]:\n        add(_iri(eid), \"proof:citedAs\", v)\n    for r in tr.get(\"reconciliation\", []):\n        rn = _iri(cid + \"_recon_\" + r[\"alert_id\"])\n        add(rn, \"a\", \"proof:Reconciliation\")\n        add(_iri(r[\"alert_id\"]), \"proof:hasReconciliation\", rn)\n        add(rn, \"proof:alertedAmount\", _lit(float(r[\"alerted_gbp\"])))\n        add(rn, \"proof:explainedAmount\", _lit(float(r[\"explained_gbp\"])))\n        add(rn, \"proof:profileAmount\", _lit(float(r.get(\"profile_gbp\") or 0)))\n        add(rn, \"proof:unexplainedAmount\", _lit(float(r[\"unexplained_gbp\"])))\n        add(rn, \"proof:cleared\", _lit(bool(r[\"cleared\"])))\n        if r.get(\"list_status\"):\n            add(rn, \"proof:listStatus\", _lit(r[\"list_status\"]))\n        for d in r.get(\"explained_by\", []):\n            add(rn, \"proof:explainedBy\", _iri(d))\n        for t in r.get(\"unexplained_txns\", []):\n            add(rn, \"proof:unexplainedTxn\", _iri(t))\n    return T\n\n\nTTL_HEADER = (\"@prefix proof: <%s> .\\n@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .\\n\"\n              \"@prefix pd: <https://proof.example/data/%s/> .\\n\\n\")\n\n\ndef run_case(world, case, want_kg=False):\n    cs = Case(world, case)\n    try:\n        code, reason, ev, extra = decide(cs)\n        fell = False\n        if not extra.get(\"reconciliation\"):\n            advisory_reconcile(cs, extra)\n    except Exception as err:  # never CLOSE on failure\n        code, reason = fallback(cs, err)\n        ev, extra, fell = [a[\"alert_id\"] for a in cs.alerts], {\"error\": repr(err)}, True\n    verdict = VERDICT_OF.get(code, \"ESCALATE\")\n    reason = clamp_reason(reason, cs)\n    ev = finalize_evidence(cs, ev, code)\n    if not ev:\n        ev = sorted(a[\"alert_id\"] for a in cs.alerts)\n    out = {\"case_id\": cs.id, \"alert_ids\": list(case.get(\"alert_ids\", [])), \"verdict\": verdict, \"reason_code\": code,\n           \"reason\": reason, \"evidence\": ev}\n    tr = build_trace(cs, code, verdict, ev, extra)\n    tr[\"fallback\"] = fell\n    if fell:\n        tr[\"error\"] = extra.get(\"error\")\n    if want_kg:\n        tr[\"_kg\"] = kg_triples(cs, tr, out)\n    return out, tr, fell\n\n\ndef main(argv):\n    args = [a for a in argv[1:] if not a.startswith(\"--\")]\n    trace = \"--trace\" in argv\n    pol = [a.split(\"=\", 1)[1] for a in argv[1:] if a.startswith(\"--policy=\")]\n    if len(args) != 2:\n        sys.stderr.write(\"usage: run <institution_folder> <output.jsonl> [--trace] [--policy=overrides.json]\\n\")\n        return 2\n    folder, outp = args\n    world = World(folder)\n    if pol:\n        applied = load_policy_overrides(pol[0], world.inst)\n        sys.stderr.write(\"policy overrides for %s: %s\\n\" % (world.inst, json.dumps(applied, sort_keys=True)))\n    lines, tlines, kg, falls = [], [], set(), 0\n    for case in world.cases:\n        try:\n            o, tr, fell = run_case(world, case, trace)\n        except Exception as err:\n            o = {\"case_id\": case.get(\"case_id\"), \"alert_ids\": list(case.get(\"alert_ids\", [])), \"verdict\": \"RFI\",\n                 \"reason_code\": \"RFI_SOURCE_OF_FUNDS\",\n                 \"reason\": \"Automated review could not complete; ask the customer for evidence of the source and \"\n                           \"purpose of the alerted funds.\", \"evidence\": sorted(case.get(\"alert_ids\", []))}\n            tr, fell = {\"case_id\": case.get(\"case_id\"), \"fallback\": True, \"error\": repr(err)}, True\n        falls += fell\n        kg |= tr.pop(\"_kg\", set())\n        lines.append(json.dumps(o, ensure_ascii=False))\n        tlines.append(json.dumps(tr, ensure_ascii=False, sort_keys=True))\n    with open(outp, \"w\", encoding=\"utf-8\") as fh:\n        fh.write(\"\\n\".join(lines) + (\"\\n\" if lines else \"\"))\n    if trace:\n        with open(outp + \".trace.jsonl\", \"w\", encoding=\"utf-8\") as fh:\n            fh.write(\"\\n\".join(tlines) + (\"\\n\" if tlines else \"\"))\n        with open(outp + \".kg.ttl\", \"w\", encoding=\"utf-8\") as fh:\n            fh.write(TTL_HEADER % (ONTO_NS, re.sub(r\"\\W\", \"_\", world.inst)))\n            fh.write(\"\\n\".join(sorted(kg)) + \"\\n\")\n    sys.stderr.write(\"%d cases, %d fallback\\n\" % (len(lines), falls))\n    return 0\n\n\nif __name__ == \"__main__\":\n    sys.exit(main(sys.argv))\n", "run_sha256": "3b7724002d5e054ff02b8aaddae6e265e26e9728d54fdbe9d27e98a7aeffdc3c"};
